pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (minimize post_residual). 
    // If bin is new, penalize opening it unless necessary.
    if bin_residual == bin_capacity {
        score += 45.0; // High barrier to opening a new bin
    }

    // 2. Lookahead Synergy: If post_residual perfectly accommodates the next item, 
    // significantly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            // Reward bins that maintain enough space for the next item
            score -= 10.0;
        } else {
            // Penalize creating "dead space" that cannot fit the next item
            score += 15.0;
        }
    }

    // 3. Mean Residual Balancing: Avoid creating bins that are outliers compared to the average.
    // If current bin's post_residual is much lower than the mean, it's a tight pack (Good).
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    // 4. Scarcity Penalty: If this is the only bin that fits, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, 
    // become more aggressive in packing to avoid leaving many bins partially full.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin opening proportional to progress to encourage consolidation late-game
    let mut score = if is_new_bin {
        15.0 + (progress * 40.0)
    } else {
        post_residual as f64
    };

    // Penalty for creating "fragmented" space (residual < 20)
    // We scale this penalty by the lookahead: if next_item_size is large, small residuals are worse
    if !is_new_bin && post_residual < 20 {
        let fragmentation_penalty = (20.0 - post_residual as f64) * (1.0 + (next_item_size as f64 / 50.0));
        score += fragmentation_penalty;
    }

    // Encourage bins that are closer to the mean residual to keep distribution uniform
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // Favor filling bins that are the last ones capable of holding the current item
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Adjust for lookahead: if next item is large, prefer bins that can still fit it
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    score
