pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) more heavily as the stream progresses, 
    // favoring tight fits early and flexible bins late.
    // Exponential term creates a "valley" for optimal residual sizes.
    let base_score = post.powf(1.5) + (100.0 - post).exp() * 0.01;

    // Penalty for opening new bins: if this is an empty bin (bin_residual == bin_capacity),
    // apply a cost that scales with progress to prevent premature fragmentation.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 150.0 + (open_bins_count as f64 * 5.0)
    } else {
        0.0
    };

    // Factor in lookahead: if next_item_size fits in post_residual, reward this placement
    // to keep bins packed efficiently for the immediate future.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Use mean_residual to balance the load across open bins. 
    // If this bin is significantly emptier than the average, penalize it slightly 
    // to favor filling up already "crowded" bins first.
    let load_balancing = if bin_residual > (mean_residual as u32) {
        (bin_residual as f64 - mean_residual) * 0.5
    } else {
        0.0
    };

    base_score + new_bin_penalty + lookahead_bonus + load_balancing
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
