    }

    // 4. Global state: encourage packing tighter as the stream progresses
    // As we approach the end of the stream, we become more "desperate" to close bins
    if fitting_bins_count == 1 && post_residual > 10 {
        score -= 20.0 * progress;
    }

    // 5. New Bin logic:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the mean_residual of existing bins is already very low,
    // or if the current item is very large and would leave a poor residual elsewhere.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // High penalty for opening a new bin early in the stream
            score = 60.0 + (mean_residual * 0.5);
            // If the current item is large, make it slightly more attractive to start a new bin
            if item_size > 60 {
                score -= 25.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #461: Harmonic-Residual Balancing
