        }
    }

    // 4. Global Density Control: Use open_bins_count to normalize aggressiveness.
    // If we have many open bins, we become more selective (higher penalty for poor fits).
    score += (open_bins_count as f64 * 0.5) * (1.0 - progress);

    // 5. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // Only choose a new bin if the current mean_residual is very low (meaning existing bins are tight).
    if bin_residual == bin_capacity {
