        score -= 200.0;
    }

    // 4. New Bin Logic:
    // Only open a new bin if the current mean_residual is very low (implying we need to pack tighter)
    // or if the item_size is large and we want to preserve space in existing bins.
    if bin_residual == bin_capacity {
        if mean_residual < 20.0 && item_size < 50 {
            score += 500.0; // Penalize new bin creation if existing bins are tight
        } else {
