        }
    }

    // 5. Progression weighting:
    // As we near the end of the stream, prioritize clearing residuals over saving space
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize configurations that leave small, unusable slivers.
    // If post_residual is tiny (1-9), it often creates "dead space" that cannot fit any future item.
    if post_residual > 0 && post_residual < 10 {
