    let mut score = post;

    // Penalty for creating "dead space" (small, unusable residuals)
    // We penalize residuals that are smaller than the smallest likely future items (e.g., < 10)
    // but only if they are not exactly 0 (which is perfect).
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead influence: If next_item_size is large, avoid bins that leave little space
    // relative to the next item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 2.0;
        }
    }

    // Dynamic thresholding: As the stream progresses, increase the cost of opening 
    // a new bin (where bin_residual == bin_capacity) to force consolidation.
    if bin_residual == bin_capacity {
