    // 1. Dead Space Penalty: If the post_residual is small but > 0, it creates a "sliver" 
    // that is likely unusable (less than 10, given item size range 10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Open Bin Pressure: Penalize opening a new bin if we have plenty of open bins,
    // or reward it if we are near the end of the stream and need to consolidate.
    if bin_residual == bin_capacity {
        // New bin candidate logic:
        // Only open a new bin if the current open bins are becoming too fragmented.
        score += (open_bins_count as f64 * 2.5) - (progress * 10.0);
    } else {
        // Favor bins that are already open to keep open_bins_count low.
        score -= (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead / Next Item Coupling:
    // If next_item_size is large, avoid leaving a residual that is too small to fit anything.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // This placement creates a gap that cannot fit the next item.
            score += 30.0;
        }
    }

    // 4. Fitting Constraint: 
    // If this is the only bin that can fit the item, prioritize it heavily to avoid 
    // unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
