    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // We penalize high post_residual to encourage tight packing.
    let mut score = post * post;

    // Penalty for leaving "dead space" that is too small for future items.
    // If the post_residual is smaller than the smallest likely item (e.g., 10),
    // it becomes "dead space". We penalize this quadratically.
    if post < 10.0 {
        score += (10.0 - post).powi(3);
    }

    // Lookahead logic: If a future item exists, penalize bins that cannot fit it.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += 500.0 * (1.0 - progress);
    }

    // Dynamic thresholding: As we approach the end of the stream, 
    // prioritize closing bins (lower post_residual) over opening new ones.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We only pick this if the cost of placing in existing bins is higher 
        // than this threshold.
        score = 2500.0 + (progress * 1000.0);
    } else {
        // If this bin is the last one that can fit the item, give it a significant
        // "sunk cost" bonus to prevent opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 1000.0;
        }
    }

    // Coupling with mean_residual: If this bin is significantly worse than 
    // the average bin, penalize it to force concentration of items.
    if post > mean_residual {
        score += (post - mean_residual).powf(1.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want to minimize post_residual, but we also want to avoid "fragile" bins.

    // 2. Harmonic Class Logic:
    // If post_residual is small (e.g., < 10), it's a "tight" fit. 
    // If post_residual is large but fits the next_item_size, we prioritize that bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that perfectly accommodate the next item
            score -= (next_item_size as f64) * 1.5;
        } else {
            // Penalize bins that leave a gap too small for the next item
            score += (bin_capacity - post_residual) as f64 * 0.2;
        }
    }

    // 3. Thresholding based on bin state:
    // Avoid opening new bins unless the existing bins are highly inefficient
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 && mean_residual > 25.0 {
            // If existing bins are mostly empty, force-use them by penalizing new bin
            score += 60.0;
        } else {
            // Otherwise, new bins are moderately penalized
            score += 45.0;
        }
    }

    // 4. Harmonic Modulo Bias:
    // Penalize post_residuals that are "awkward" (e.g., leaving 1-5 space which is useless for most items)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 5. Progression scaling:
    // As we reach the end of the stream, prioritize closing bins over opening new ones
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
