    if next_item_size > 0 {
        let lookahead_penalty = (next_item_size as f64 - post_res).max(0.0).powf(1.5);
        score += lookahead_penalty * (1.0 - progress);
    }

    // New bin penalty: If we have fitting bins, heavily penalize opening a new one.
    // If no bins fit, the 'new bin' score becomes the baseline.
    if is_new_bin {
