    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #86: Harmonic Residual Optimization
    // Targets "Best Fit Decreasing" behavior while dynamically punishing 
    // fragment sizes that cannot accommodate the lookahead item.

    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones":
    // Small residuals are dangerous. We penalize post_residual heavily if it's 
