    }

    // 3. Density Normalization:
    // Prefer bins that are closer to the mean residual to keep bins balanced.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // to discourage opening new bins unless the fit into existing bins is catastrophic.
    if bin_residual == bin_capacity {
        // Penalty is modulated by how many bins are already open to prevent explosion
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Fitting Constraint:
    // If this is the only bin that can fit the item, prioritize it heavily (Negative score).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 6. Harmonic Tiering:
    // Favor residuals that align with common item sizes (e.g., 20, 25, 33, 50).
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    score
}

