    // Heavily penalize opening a new bin if other bins can fit the item.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 150.0 + (100.0 * (1.0 - progress));
        } else {
            score -= 20.0; // Encourage opening a new bin only when necessary
        }
    }

    // 4. Global state coupling: 
    // If the mean residual is high, we are currently wasting space. 
    // Force tighter packing by penalizing bins that leave more than the current mean residual.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Critical constraint: If this is the last chance to fit the item in existing bins,
    // reduce the penalty for a poor fit to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

