    let mut score = post;

    // Penalty for creating a "sliver" (fragmentation): 
    // Small residuals are hard to fill later. 
    // We penalize post_residual ranges that are likely to be unusable (e.g., < 10).
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.5;
    }

    // Lookahead logic:
    // If the next item can fit into this post_residual, reward this bin placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0 * (1.0 - progress);
    }

    // Dynamic thresholding:
    // As the stream progresses, become more aggressive in filling bins (Best Fit).
    // Early on, allow more flexibility; towards the end, minimize open_bins_count.
    let density_factor = (open_bins_count as f64) * (1.0 - progress);
    score += density_factor * 2.0;

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // Penalize this relative to the difficulty of fitting the current item into existing bins.
    if bin_residual == bin_capacity {
        // As progress increases, the cost of opening a new bin should be higher 
        // to force consolidation.
        score += 40.0 * (1.0 + progress);

        // If there are many bins that could have fit this item, don't open a new one.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 10.0;
        }
    }

    // Interaction with mean_residual:
    // Avoid creating bins that are significantly worse than the current average.
    if post > mean_residual {
        score += (post - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

