    }

    // 2. Lookahead Integration: If the next item can fit in the post_residual, 
    // we heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
