    // 4. Harmonic/Modulo pressure: Penalize residuals that create "awkward" gaps.
    // If post_residual is a multiple of 20, it's likely a good alignment for future items (20, 40, 50).
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // 5. Global density pressure: As the stream progresses, favor packing tighter 
    // to reduce the total number of open bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64);

    // 6. Avoid fragmenting bins when many are already open.
    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
