    // Pressure to consolidate: Penalize opening new bins when current ones have capacity.
    // If this is a new bin (bin_residual == bin_capacity) and we have other fitting options,
    // apply a heavy penalty to discourage its selection.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // prioritize this bin to reduce fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // Global state adjustment: As we approach the end of the stream, 
    // be more aggressive about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward tight packing: If post_residual is small, it's a good fit.
    // However, if it's too small (e.g., < 10), it might be "dead space".
    if post_residual < 10 {
