    }

    // 4. Balancing with global state: Avoid creating many bins with high residuals.
    // If this bin's residual is significantly higher than the mean, penalize it.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 2.0;
    }

    // 5. Progression adjustment: As we reach the end of the stream, 
    // be more aggressive about closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 10.0);

