}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score. Lower is better.
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that are unlikely to fit any future items)
    // If post_residual is small but not zero, it's often a bad fit.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global state awareness: If we have many open bins, we should be more aggressive about filling
    // existing ones rather than opening new ones.
    if bin_residual == bin_capacity {
