        score += 30.0 + (open_bins_count as f64 * 2.0);

        // If we are near the end of the stream, opening a new bin is very costly.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 100.0;
    } else {
        // This is an existing bin. Reward filling it if it helps bring its residual 
        // closer to the mean_residual of other bins (balancing).
        let imbalance = (post_residual as f64 - mean_residual).abs();
        score -= imbalance * 0.2;
    }

    // 4. Scarcity handling: If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
