    } else {
        // If it's an existing bin, reward bins that align with the mean residual
        // to keep bin fullness balanced.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;

        // If this is the only bin that fits, prioritize it heavily
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

