    }

    // Harmonic preference: encourage filling bins to capacity using modulo arithmetic
    // to favor placements that result in "clean" bin states (multiples of 20).
    let harmonic_fit = (post_residual % 20) as f64;
    score += harmonic_fit * 0.5;

    // Progression scaling: as the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space": post_residuals between 1 and 9 are extremely hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
