    // 2. Lookahead optimization: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open bins pressure: If there are many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, this is a "new bin" request.
    if bin_residual == bin_capacity {
