    // 4. Tightness bias: Favor bins that are already nearly full (Best Fit derivative).
    // The smaller the post_residual, the better, unless it enters the "dead zone".
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // 5. Progression scaling: As we approach the end of the stream, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (leaving too much empty space).
    // This is the base of our score.

    // 2. Lookahead Synergy: If the post_residual is nearly perfect for the next item, 
    // heavily reward this bin to keep the packing density high.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward small gaps between post_residual and next_item_size.
        score -= 50.0 / (1.0 + diff);
    }

    // 3. Last Chance Logic: If this is the only bin that can fit the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
