    }

    // 4. Global Density Balancing: Compare the bin's state to the population mean.
    // If this bin's residual is significantly lower than the mean, we are effectively 
    // compressing this bin, which is good.
    if mean_residual > 0.0 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. New Bin Threshold: If we are considering a brand new empty bin,
    // only pick it if the penalty for using existing bins is extremely high.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low, 
        // suggesting that current bins are already well-packed.
        score += 45.0 - (open_bins_count as f64 * 0.1);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit)
    // The base score is already post_residual.

    // 2. Dead Space Penalty: Penalize creating a bin with very small residual
    // If post_residual is small (e.g., < 10) but not 0, it's often a "waste" 
    // unless it perfectly closes the bin.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic (Next Item):
    // If the next item is large, favor keeping larger residuals open.
    if next_item_size > 0 {
        let potential_next_residual = post_residual as i32 - next_item_size as i32;
        if potential_next_residual < 0 {
            // If the next item won't fit in this bin, penalize this choice
            // slightly to keep this bin for smaller items.
            score += 15.0 * (next_item_size as f64 / 100.0);
        } else {
            // If it fits, reward this bin as it consolidates future items.
            score -= 20.0 * (next_item_size as f64 / 100.0);
        }
    }

    // 4. Global State: Manage fragmentation
    // If mean_residual is high, we have many under-utilized bins. 
    // Discourage opening new bins (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // 5. Scarcity/Fitting Pressure:
    // If this is the only bin that fits the item (fitting_bins_count == 1),
    // prioritize using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // 6. Dynamic Scaling:
    // As we reach the end of the stream, prioritize packing tightly regardless of fragmentation.
    score *= 1.0 + (0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
