        score += 15.0 * (1.0 - progress);

        // If there are many open bins, penalize opening another one
        score += open_bins_count as f64 * 0.5;
    }

    // Favor bins that align with the global mean residual to keep distribution uniform
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.1;

    // Critical constraint: If this is the only bin that fits, we must take it (lower score significantly)
    if fitting_bins_count == 1 && res != cap {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
