                score += 8.0;
            }
        }

        // Penalty for high fragmentation: if this placement results in a residual 
        // smaller than the smallest likely items (e.g., < 10), it's often wasted space.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Balancing: Favor bins that keep the mean residual of all open bins consistent.
    // This discourages "stretching" one bin while leaving others mostly empty.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * residual_diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // We prioritize bins that leave the smallest residual.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead logic (k=2):
    // If the next item fits into the current post_residual, we reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (100.0 - next_item_size as f64) * 1.5;
    }

    // 3. Harmonic class awareness:
    // Large items (>= 50) are hard to fit, prioritize keeping them together.
    // If we have a large item, we penalize bins that have a small residual 
    // that cannot accommodate another large-ish item.
    if item_size > 50 {
        if post_residual > 0 && post_residual < 30 {
            score += 20.0;
        }
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless the open bins are already very full (mean_residual is low).
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    }

    // 5. Scarcity/Fitting logic:
    // If this is the last chance to fit the item in an existing bin, 
    // significantly reduce the score to prevent opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progression scaling:
    // As we near the end of the stream, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // (1-9) which are effectively "dead" if they appear late in the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy premium.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the item is large.
        // Penalty scales with the number of existing bins.
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 3. Lookahead Integration: If the next item is large, favor keeping space open.
    // If post_residual is not enough for the next item, penalize slightly.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // prioritize it to avoid forcing a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If the bin residual is already smaller than the mean,
    // favor packing into it to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (small residual that cannot fit typical items)
    // We penalize residuals that are smaller than the smallest likely item (10) 
    // unless the residual is exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead matching: reward bins where the post_residual can fit the next item.
    // If post_residual perfectly matches next_item_size, we favor it heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (bin_capacity - post_residual) as f64 * 0.5;
            if post_residual == next_item_size {
                score -= 40.0;
            }
        }
    }

    // 3. Density balancing: favor bins that stay closer to the mean residual of the system.
    // This prevents creating a single very full bin while others are very empty.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 4. Force efficiency: If this is the last fitting bin, prioritize it to avoid 
    // opening a new bin unnecessarily, but only if the fit isn't catastrophic.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. New Bin Policy: High penalty for opening new bins unless the fit is bad.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average current efficiency is very high,
        // or if we are late in the stream and need to clear out space.
        let progress = step_index as f64 / total_items as f64;
        score += 35.0 + (progress * 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (tiny gaps that are hard to fill).
    // Specifically, gaps between 1 and 9 are extremely difficult to fill given the input range.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead: If placing this item prevents the next item from fitting, penalize.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 35.0;
    }

    // 3. Dynamic Thresholding: As the stream nears completion, prioritize packing 
    // tightly to close bins, rather than starting new ones.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 45.0;
        // Increase penalty as we near the end of the stream to force consolidation
        score += (progress * 40.0);
    } else {
        // Reward bins that are becoming "full" (Best Fit approach)
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 4. Global State: If we have many open bins, penalize opening a new one 
    // even more severely to encourage utilizing existing fragmented space.
    if bin_residual == bin_capacity && open_bins_count > 5 {
        score += (open_bins_count as f64) * 5.0;
    }

    // 5. Residual Balancing: Favor bins whose resulting residual is closer to the 
    // mean residual of all open bins to maintain a uniform "fill" across the set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Last Chance Logic: If this is the only bin that can fit the item, 
    // reduce the penalty to ensure we don't unnecessarily open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual, which we want to minimize (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: scales with progress to avoid fragmentation early on.
    // As the stream nears the end, we become more aggressive in opening new bins to accommodate large items.
    if is_new_bin {
        score += 15.0 + (35.0 * (1.0 - progress));
        // If we have many bins open, penalize opening more to enforce consolidation.
        score += (open_bins_count as f64) * 0.5;
    }

    // Lookahead logic: if the next item is large, favor keeping space available (penalty for tight fits).
    if next_item_size > 0 {
        let tightness = (post_residual as f64) / (next_item_size as f64);
        if tightness < 0.5 {
            score += 10.0 * (1.0 - tightness);
        }
    }

    // Reward bins that are closer to the mean residual (load balancing).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * deviation;

    // If this is the only bin that fits, prioritize it heavily by reducing the score.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Penalty for creating a "dead zone" (very small residual that is likely unusable).
    // Assuming effective item size is typically > 15, residuals under 10 are dangerous.
    if post_residual > 0 && post_residual < 12 {
        score += 15.0 * (1.0 - (post_residual as f64 / 12.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "wasteland" bins (small residuals that cannot fit common items)
    // We heavily penalize residuals that are smaller than the smallest likely future items (10)
    // but larger than 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // Best Fit Decreasing logic: Favor bins that leave the least space (lower post_residual).
    // This is already inherent in the base score.

    // Lookahead logic: If the next item can fit in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Harmonic/Modulo logic: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 50).
    // This leaves the bin in a state that is more likely to accept future items perfectly.
    let harmonic_alignment = (post_residual % 20) as f64;
    score += harmonic_alignment * 0.5;

    // Handle new bin opening:
    // Only open a new bin if the current options are extremely poor (forcing a high score).
    if bin_residual == bin_capacity {
        // If we have fitting bins, make opening a new bin expensive unless open_bins_count is low.
        if fitting_bins_count > 0 {
            score += 65.0 + (open_bins_count as f64 * 2.0);
        } else {
            // No choice, must open new bin.
            score = 0.0;
        }
    }

    // Progression weight: In the final stages, be more conservative with space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver": space too small for the smallest possible item (10).
    // We penalize post_residual values between 1 and 9 heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
