    // Pressure: If we are near the end of the stream, prioritize closing bins to reduce total count.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    // Favor bins that are already "tight" (Best Fit logic).
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other bin fits.
    // This forces the heuristic to prefer existing bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0;
        } else {
            score -= 5.0; // Base cost for opening a new bin when necessary
        }
    }

    // If this bin is the only one that fits, give it a significant boost.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

