        }
    }

    // 4. Mean Residual Coupling: Prefer bins that keep the bin closer to the mean 
    // to consolidate free space.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
