}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: Primary metric (Best Fit).
    // Penalize large gaps that are too small for common items (10-30 range).
    // Reward bins that leave space for the lookahead item.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. If this is a new bin (bin_residual == bin_capacity), penalize it based on how many bins are already open.
    // We only want to open a new bin if the existing fits are "too tight" or "too wasteful".
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.5) + (progress * 10.0);
    } else {
        // 2. Penalty for creating unusable space (fragmentation).
        // If the post_residual is small but not zero, it's often worse than a slightly larger residual.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // 3. Lookahead optimization: If the next item fits, reward bins that leave enough space for it.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 12.0;
            } else if post_residual > 0 {
                // If it doesn't fit, but we are near the end of the stream, prioritize clearing current bins.
                score += (1.0 - progress) * 5.0;
            }
        }

        // 4. Global state adjustment: If we have many open bins, prioritize filling the emptiest ones.
        // mean_residual helps identify if we are spreading items too thin.
        if (post_residual as f64) > mean_residual {
            score += 5.0;
        } else {
            score -= 5.0;
        }
    }

    // 5. If this is the only bin that fits, we must take it (strong incentive).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
