    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating small, unusable gaps (the "fragmentation" penalty)
    // We target a post_residual that is either 0 (perfect fit) or large enough to accommodate future items.
    let fragmentation_penalty = if post_res > 0.0 && post_res < 10.0 {
        20.0 * (10.0 - post_res)
    } else {
        0.0
    };

    // Reward bins that maintain a residual close to the mean_residual of other bins,
    // encouraging uniform bin filling to minimize the variance of open bin capacities.
    let uniformity_bonus = (post_res - mean_residual).abs() * 0.5;

    // Incorporate lookahead: if next_item_size fits in the current post_residual, reduce penalty.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -15.0 * (next_item_size as f64 / 100.0)
    } else {
        0.0
    };

    // Progress-based scaling: As the stream nears completion, become more conservative 
    // about opening new bins (heavily penalize empty bin selection).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        40.0 + (progress * 60.0)
    } else {
        0.0
    };

    // Favor bins that have fewer fitting options to consolidate items into "nearly full" bins
    let scarcity_bonus = if fitting_bins_count == 1 { -10.0 } else { 0.0 };

    // Base score: prioritize smaller post_residual (Best Fit principle), modified by non-linear factors.
    let mut score = post_res + fragmentation_penalty + uniformity_bonus + lookahead_bonus + new_bin_penalty + scarcity_bonus;

    // Dampen the score for very full bins to ensure they are filled completely
    if post_res < 5.0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
