    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. Mean Residual Alignment: Penalize bins that deviate too far from the mean
    // to keep the packing uniform across all active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize the post_residual (Best Fit), but penalize placements that leave
    // a "dead zone" (gaps < 10) if a lookahead item could have filled it better,
    // and modulate aggressiveness based on the progression through the stream.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space": gaps smaller than the minimum item size (10) are usually wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead optimization: If the next item fits perfectly into the current post_residual,
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_diff) * 0.5;
    }

    // 3. New bin penalty: Only open a new bin if the current mean_residual is very low,
    // indicating that we are running out of space in existing bins, or if there is no other choice.
    if is_new_bin {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Gradually reduce the cost of opening a new bin as we approach the end of the stream
            // to ensure we don't end up with many half-full bins at the very end.
            let progress = step_index as f64 / total_items as f64;
            score = 45.0 + (mean_residual * 0.5) - (progress * 20.0);
        }
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item, prioritize it
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
