pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the smallest residual.
    // The base score (post_residual) already prioritizes tighter fits.

    // 2. Penalty for creating "dead space": If post_residual is small but not zero,
    // it often traps space that can't fit many future items (bins < 10 are often wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

