            // unless we are very early in the stream.
            score += 60.0 * (1.0 - progress);
        }
    } else {
        // 5. Global state normalization: If the average residual of open bins is high,
        // we are being too wasteful. Penalize choosing bins that increase the mean residual.
        if (post_residual as f64) > mean_residual {
            score += 15.0;
        }
    }

    // 6. Final adjustment: Encourage filling bins that are already "half-full" 
    // to consolidate space, especially as the stream nears the end.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
