    // Penalty for creating "dead space": residues that are too small to fit the next item
    // but large enough to waste capacity.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Encourage filling bins that are already partially full (higher mean_residual implies many empty bins)
    // We subtract a fraction of the bin_residual to prioritize bins that are already "closing"
    score -= (bin_capacity - bin_residual) as f64 * 0.2;

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // If we have fitting bins, opening a new one is very expensive
        if fitting_bins_count > 0 {
            score += 120.0;
        } else {
            // If no bins fit, we must open a new one, but we prioritize the "cleanest" state
            score -= 50.0;
        }
    }

    // Harmonic adjustment: Penalize post_residuals that are in the "awkward" range (1-9)
    // where they cannot fit most items (10..80) but waste bin space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Progression awareness: As we near the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

