        }
    } else {
        // Existing bin: reward bins that are getting closer to capacity.
        // We favor filling bins that are already "fuller" than the global average.
        if (bin_capacity - bin_residual) as f64 > mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // 4. Criticality check:
    // If this is the only bin that can fit the item, we must take it (lower score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
