    let mut score = post;

    // Penalty for creating 'fragmented' space (small residuals that are hard to fill).
    // We penalize residuals between 1 and 9 significantly as they are difficult to fill.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // significantly reward this placement (Best Fit Decreasing dynamic).
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 40.0;
