    // 2. Lookahead penalty: If the next item cannot fit into the current post_residual,
    // we penalize this placement to keep space available for the lookahead.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // 3. Fragmentation avoidance: Penalize creating "dead space" (very small residuals).
    // If post_residual is less than the minimum possible item size (10), it's likely waste.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // 4. Global state pressure: If we have many open bins, we become more aggressive
    // about filling them (Best-Fit). If we have few, we are more conservative.
    let density_factor = (open_bins_count as f64) / (1.0 + (step_index as f64 / total_items as f64).max(0.1));
    score += density_factor * 2.5;

    // 5. New bin threshold: If this is an empty bin, add a base cost to discourage
    // opening new bins unless the fit in existing bins is truly terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Adjust new bin cost based on how many bins can actually fit the item.
        // If no other bins can fit the item, reduce the penalty for opening a new one.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // 6. Mean residual coupling: If the current bin's post_residual is significantly
    // better than the global mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish large post_residuals (Best Fit logic)
    // We want post_residual to be as close to 0 as possible.
    let mut score = post_residual as f64;

    // Penalty for creating a new bin:
    // As the stream progresses, we want to be more conservative about opening new bins.
    if is_new_bin {
        score += 15.0 + (progress * 40.0);
    }

    // Lookahead interaction:
    // If the next item is large, we want to reserve space in current bins.
    // If post_residual is smaller than next_item_size, we penalize it as it wastes potential fitting space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Dynamic pressure: 
    // If many bins are open, discourage opening another one (penalize new bins).
    // If fitting_bins_count is 1, this bin is critical; give it a slight preference (negative bias).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0;
    }

    // Non-linear coupling with mean_residual:
    // If the current bin's post_residual is much worse than the global mean, penalize it.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead zones': residuals that are too small to fit typical future items
    // but large enough to waste capacity. We penalize post_residuals in the range [1, 19].
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // Lookahead logic: if next_item_size is large, prioritize bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that leave exactly enough room for the next item
            score -= 15.0 * (1.0 - (post_residual as f64 - next_item_size as f64).abs() / 100.0);
        }
    }

    // Harmonic class logic: penalize bins that deviate significantly from the mean residual
    // to encourage bin packing uniformity.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // If this is the only bin that can fit the item, we heavily discount the score
    // to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New bin threshold: Only open a new bin if the current fit is very poor (post_residual > 60)
    // or if we are nearing the end of the stream and need to consolidate.
    if bin_residual == bin_capacity {
        if post_residual > 60 {
            score += 30.0;
        } else {
            score += 100.0;
        }

        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Strict Best-Fit with aggressive penalty for "unusable" gaps (1..9 range)
