    let mut score = post_residual as f64;

    // 1. Penalize unusable small gaps (1-9) which are unlikely to fit future items.
    // This forces the algorithm to prefer "tighter" fits or larger residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
