    // room for the next_item_size.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that would be unable to accommodate the next item.
            score += 15.0;
        } else {
            // Reward bins that have a "perfect" fit for the predicted next item.
            if (post_residual - next_item_size) < 5 {
                score -= 10.0;
            }
        }
    }

    // 4. Global pressure: As the stream nears completion, reduce penalty for opening bins
    // to ensure no items are left behind due to overly restrictive heuristics.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins heavily, but scale by progress to allow flexibility near the end.
    if is_new_bin {
        score += 45.0 + (30.0 * (step_index as f64 / total_items as f64));
