    // If the next item fits perfectly into the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= (35.0 - diff).max(0.0);
    }

    // 3. Avoid creating "sliver" bins (unusable space < 10) unless necessary.
    // If post_residual is small but > 0, it's often a dead-space trap.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Balance current bin usage against the mean_residual.
    // If this bin's post_residual is significantly worse than the average, penalize.
    if !is_new_bin && (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 5. If this is the only bin that can fit the item, prioritize it to keep bin count low.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }

    // 6. Prefer filling bins that are already partially filled over fresh ones.
    if !is_new_bin {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
