            score += 20.0 * (1.0 - progress);
        }
    }

    // Heuristic for opening a new bin:
    // If we have many open bins, penalize opening a new one. 
    // If we have very few, be more permissive if the fit is poor.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We only pick this if the cost of placing in existing bins is high (e.g., leaving a small gap).
        score = 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Reward bins that keep the mean_residual high (balanced distribution) 
        // to keep options open for future large items.
        score -= (mean_residual - post) * 0.2;
    }

    // Coupling: If this is the last chance for the current item, prioritize fitting it 
    // over the ideal residual size.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // We prioritize bins that result in small post_residuals (tight fit).
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic:
    // If post_residual is a small divisor of bin_capacity, it's often a "good" leftover.
    // Penalize residuals that are awkward fractions (e.g., 1-9) to force tight packing.
    if post_residual > 0 && post_residual < 10 {
