    // If the next item is large, we want a bin that can accommodate it.
    // If this bin's post_residual is smaller than next_item_size, it's a "dead" bin for the future.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it
    // unless we have no other choice or the mean residual is already quite low.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If there are many open bins, we are likely fragmenting; penalize new bins more.
        score += (open_bins_count as f64) * 5.0;
    }

    // 5. Urgency:
    // If this is the only bin that fits the current item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. Global Efficiency:
    // If the bin's residual is significantly better than the global mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
