        // if the current fitting options are all creating bad slivers.
        score += (open_bins_count as f64) * 5.0;

        // As we reach the end of the stream, discourage new bin creation.
        score += (progress * 100.0);
    } else {
        // If we are fitting into an existing bin, reward it based on how much 
        // space we save compared to the mean_residual.
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 5. Last Chance Logic: If this is the only bin that fits, we must take it
    // unless it is an exceptionally poor fit (e.g. leaving a tiny sliver).
    if fitting_bins_count == 1 && !is_new_bin {
        if post_residual < 5 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

