        score += diff * 0.8;

        // Reward cases where the next item fits perfectly
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // 3. Balancing load across open bins:
    // If the bin's residual is significantly better than the global average, favor it.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 4. Strategic New Bin Management:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily unless
    // there are no other options or the fit is exceptionally poor in all other bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the current item is very large or if we have many bins
            // and we want to preserve the tight packing of existing bins.
            score += 45.0 + (open_bins_count as f64 * 0.5);
        } else {
            // Forced new bin
            score = 0.0;
        }
    } else {
        // Favor bins that are already partially filled to maximize density.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, prioritize space density over lookahead.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
