    // We add a non-linear term to penalize bins that leave tiny, unusable gaps (1..9)
    let gap_penalty = if post_residual > 0 && post_residual < 10 {
        15.0 * (1.0 - (post_residual as f64 / 10.0))
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual < next_item_size, we create a "stranded" bin.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        12.0 * (1.0 - progress)
    } else {
        0.0
    };

    // New bin thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if the
    // average residual of current bins is high, suggesting we are struggling to fit items.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_base = if is_new_bin {
        // High mean_residual means we have plenty of space in existing bins; discourage new bins.
        // Low mean_residual means bins are full; encourage new bins.
        30.0 + (mean_residual * 0.5)
    } else {
        0.0
    };

    // Interaction term: As the stream progresses, prioritize tighter fits (lower post_residual)
    // to keep the number of open bins low for the final phases.
    let tightness_bonus = post * (0.1 + (0.4 * progress));

    score = tightness_bonus + gap_penalty + lookahead_penalty + new_bin_base;

    score
}

