    // for it, or aggressively clear bins to fit it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that will definitely not fit the next item.
            score += 15.0 * (1.0 - progress);
        } else {
            // Reward bins that create a "perfect" fit for the next item.
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 / (1.0 + slack as f64));
