    // (e.g., leaving a large, unusable gap) or if we are early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Penalize opening a new bin increasingly as we progress to avoid fragmentation.
        score += 40.0 + (progress * 30.0);
    }

    // 6. Global Pressure: If open_bins_count is high, consolidate into existing bins.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps smaller than the smallest likely future item).
    // If post_residual is < 10, it is likely unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead optimization: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open bins pressure: If this is an existing bin, favor it to reduce open_bins_count.
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily unless no other options exist.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many open bins, penalize opening a new one even more.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // Favor bins that are already "tight" to keep space consolidated.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Fitting constraints: If this is the last bin that can fit the item, 
    // it is a "must-take" to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Progression scaling: As we reach the end of the stream, be more aggressive 
    // about packing tightly to avoid stragglers.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Aggressive 2-step lookahead matching
    // Objective: Minimize score.

    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin prematurely
    if bin_residual == bin_capacity {
        score += 45.0; // High barrier to open new bin
        // Reduce penalty if current bins are all very tight
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // 2. Lookahead optimization: If post_residual is close to next_item_size, we favor this bin
    // This targets "perfect" pairings where the next item fits into the current bin's remainder
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward placements that leave exactly enough room for the next item
        if post_residual >= next_item_size {
            score -= (25.0 / (1.0 + diff));
        } else {
            // Penalize placements that make it impossible to fit the next item if it was otherwise possible
            score += 15.0;
        }
    }

    // 3. Pressure management: If this is the last chance for this item (fitting_bins_count == 1),
    // prioritize this bin even if it's a sub-optimal fit to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 4. Global efficiency: Favor bins that keep the mean_residual low
    // This encourages "Best Fit" behavior implicitly
    score += (post_residual as f64 - mean_residual) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
