    // 5. Fitting Constraint: If this is the only bin that fits the current item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Dynamic balance: Prefer bins that stay close to the global mean residual to keep packing uniform.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space" (small residuals that are hard to fill later)
    // We penalize residuals in the range [1, 9] heavily as they are difficult to use.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
    }

    // Dynamic threshold: As the stream progresses, become more conservative about opening new bins.
    // We add a penalty to opening new bins that scales with the progress of the stream.
    if is_new_bin {
        // The base cost of opening a new bin is 30.0. 
        // We increase this cost as we approach the end of the stream to force tighter packing.
        score += 30.0 + (progress * 40.0);
    } else {
        // Encourage using bins that are already "near full" (lower mean_residual)
        // This promotes clustering of high-density bins.
        score -= (100.0 - mean_residual) * 0.2;
    }

    // If this is the last chance for this item (fitting_bins_count == 1), 
    // significantly reduce the score to ensure we don't accidentally open a new bin 
    // when one is available.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items).
    // If post_residual is < 10, it's likely wasted space unless it's 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead logic: If the next item can fit in the post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Harmonic class alignment: Reward filling bins to "clean" thresholds (e.g., 0, 25, 50).
    // This helps group items of similar total size together.
    let remainder = post_residual % 25;
    score += (remainder as f64).powf(1.1);

    // 4. Strategic new bin avoidance: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other bin fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0; 
        } else {
            score -= 10.0;
        }
    }

    // 5. Global state normalization:
    // As the stream progresses, become more aggressive about filling existing bins 
    // to minimize the final open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64);

    // 6. Prefer bins that are already closer to being full (Best-Fit principle).
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
