    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one is available
            score += 60.0 + (mean_residual * 0.5);
        } else {
            // Neutralize score for unavoidable new bin
            score = 25.0;
        }
    }

    // 5. Fragmentation Control: Favor bins that stay close to the mean residual to keep packing uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
