pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize small residuals that create "orphaned" space (e.g., 1-9) which are hard to fill.
    // We use a sigmoid-like penalty for post_residual < 10.
    let orphan_penalty = if post_residual < 10 && post_residual > 0 {
        (10.0 - post_res) * 5.0
    } else {
        0.0
    };

    // Reward bins that tightly fit the current item, especially as we approach the end of the stream (high progress).
    // If next_item_size exists, favor bins that leave enough space for the next item (Lookahead).
    let lookahead_fit = if next_item_size > 0 && post_residual >= next_item_size {
        -20.0 * (1.0 - progress)
    } else if next_item_size > 0 && post_residual < next_item_size {
        15.0 * progress
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many bins are already open.
    // As the stream progresses, we become more aggressive in opening new bins to avoid fragmentation.
    let new_bin_penalty = if bin_residual == bin_capacity {
        40.0 * (1.0 - progress) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Interaction between mean_residual and current post_residual.
    // If the current bin is "emptier" than the average, we prefer filling it to consolidate space.
    let consolidation_bonus = if (bin_residual as f64) > mean_residual {
        -5.0 * (bin_residual as f64 / bin_capacity as f64)
    } else {
        0.0
    };

    // Final score: prioritize lower post_residual (Best Fit), modulated by stream progress and lookahead.
    let mut score = post_res 
        + orphan_penalty 
        + lookahead_fit 
        + new_bin_penalty 
        + consolidation_bonus;

    // Apply a slight bias against opening a new bin if other fitting bins exist.
    if fitting_bins_count > 0 && bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
