    // 3. Dynamic New-Bin Threshold
    // As we approach the end of the stream, discourage opening new bins unless necessary
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Apply a penalty for opening a new bin if an existing bin could fit the item
            score += 30.0 + (40.0 * progress);
        }
        // Balance the density of the new bin against the average of existing ones
        score += mean_residual * 0.5;
    } else {
        // For existing bins, favor those that get closer to the mean_residual (Best-Fit variant)
        // This keeps remaining space uniform across bins
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.2;
    }

    // 4. Global state coupling: Encourage filling bins that are already "half-full" 
    // to preserve empty capacity for future large items
    if bin_residual < (bin_capacity / 2) {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the square of the post_residual to heavily penalize large gaps (Best-Fit principle).
    let mut score = post_res.powi(2);

    // Penalty for creating small, unusable gaps (1-9) which are hard to fill later.
    // We emphasize this penalty more as the stream progresses (higher progress).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * 50.0 * (1.0 + progress);
    }

    // Lookahead logic: if next_item_size is large, avoid leaving small residuals now.
    // If next_item_size + post_residual is slightly above bin_capacity, it's a "near miss".
    if next_item_size > 0 {
        let combined = post_residual + next_item_size;
        if combined > bin_capacity && combined < bin_capacity + 15 {
            score += 40.0;
        }
    }

    // Heuristic for opening a new bin:
    // If this is an empty bin (bin_residual == bin_capacity), calculate a "threshold" 
    // cost to determine if we should start a new bin.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins early, decreases as open_bins_count increases.
        // This encourages packing into existing bins first.
        score += 250.0 * (1.0 - progress) / (1.0 + open_bins_count as f64).sqrt();
    } else {
        // If it's an existing bin, favor those that bring the mean_residual closer to 0
        // to keep bins tightly packed.
        score -= (mean_residual - post_res).abs() * 5.0;
    }

    // Penalty for scattering items across too many bins.
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
