    }

    // 4. Mean Residual Pressure: If post_residual is significantly worse than the 
    // average bin's residual, penalize it to keep bins tightly packed.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Scarcity avoidance: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Thresholding for "Impossible Fits": If post_residual is too small to fit 
    // any meaningful subsequent item (e.g., < 10), it is a "dead zone". 
    // Penalize small slivers that are likely to stay empty.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 7. Progression factor: As we reach the end of the stream, be more aggressive 
    // about filling existing bins to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
