            score += 30.0;
        }
    }

    // 4. Lookahead coupling: If the next item is large and this current placement creates 
    // a small residual that won't fit the next item, penalize that placement.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 5. Mean residual balancing: Penalize bins that deviate significantly from the mean 
    // residual of the system to encourage uniform bin filling.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-fit foundation: prioritize small post_residual (minimize waste)
    // 2. Penalty for creating "dead space": if post_residual is too small to fit common small items (e.g., < 10)
    //    but not zero, it's often worse than a slightly larger residual.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 3. Lookahead logic: if the next item fits perfectly into this post_residual, reward it heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward bins that maintain enough room for the next item
            score -= 5.0;
        }
    }

    // 4. Global state awareness:
    // If we have many bins open, we should be more aggressive about packing into existing ones.
    // If fitting_bins_count is 1, this is the last chance for this bin; prioritize filling it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 5. New Bin penalty: 
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the mean_residual is very low (suggesting we are running out of space in current bins).
    if bin_residual == bin_capacity {
        let open_penalty = 50.0 + (open_bins_count as f64 * 2.0);
        let urgency = if mean_residual < 20.0 { 10.0 } else { 0.0 };
        score += (open_penalty - urgency);
    }

    // 6. Progression dampening:
    // As we near the end of the stream, prioritize closing out bins (packing tighter).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
