        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Dynamic adjustment based on the mean residual of current bins
    // If our bins are generally empty, prefer filling them further
    if mean_residual > 30.0 {
        score -= (mean_residual - 30.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Best-Fit (minimize post_residual)
    // We penalize very small post_residuals (0-5) as they create "splinters" that are hard to fill.
    let splinter_penalty = if post_residual > 0 && post_residual < 6 {
        (6.0 - post as f64) * 15.0
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size fits in post_residual, reward this placement.
    let lookahead_reward = if next_item_size > 0 && post_residual >= next_item_size {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Dynamic threshold: As the stream progresses, we become more conservative about opening new bins.
    // If fitting_bins_count == 1, we are at the last chance; penalize opening a new bin heavily.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            50.0 + (progress * 100.0)
        } else {
            -10.0 // Necessary to open new bin
        }
    } else {
        0.0
    };

    // Interaction term: Penalize deviations from mean_residual to keep bins balanced.
    let balance_penalty = (post as f64 - mean_residual).abs() * 0.5;

    // Score synthesis: Combine terms
    // post is the primary target (Best Fit), modulated by lookahead and stream progress.
    post + splinter_penalty + lookahead_reward + new_bin_penalty + balance_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Target "Harmonic" remainders: Favor post_residuals that are multiples of 20 or small.
    // This creates "bins" for common item sizes (e.g., 20, 25, 33, 50).
    let harmonic_penalty = ((post_residual % 20) as f64).powf(1.5);
    score += harmonic_penalty;

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to avoid fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;

        // If the resulting gap is near zero, it's an "ideal" match.
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 50.0;
        }
    }

    // 3. Fragmentation Penalty: Penalize creating a bin with a very small, unusable residual
    // (e.g., between 1 and 9), as these are often "dead" space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Density Balancing: If we have many open bins, penalize opening a new one.
    // Only open a new bin if the current fit is truly terrible (high post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 {
            score += 65.0; // Strong resistance to opening new bins
        }
        // If we must open a new bin, prioritize a state that leaves room for the next item.
        if next_item_size > 0 && next_item_size <= (bin_capacity - item_size) {
            score -= 20.0;
        }
    }

    // 5. Fitting Constraint: If this is the only bin that fits the item, 
    // significantly lower its score to ensure it is selected over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    // 6. Global Trend adjustment: As we approach the end of the stream, 
    // be more aggressive about filling existing bins (lower scores for higher utilization).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
