    if post < 10.0 {
        score += 15.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If the current post_residual is too small for the next_item_size, penalize.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += 25.0 * (1.0 - progress);
    }

    // New bin avoidance: If this is an empty bin (new bin candidate),
    // penalize based on current open bin count and progress.
    // We prefer filling existing bins until the stream is near completion.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress) + (open_bins_count as f64 * 2.0);
    }

    // Global optimization: If this is the only fitting bin, reduce its score
    // to ensure we don't unnecessarily open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Coupling with mean_residual: Encourage packing that keeps the average 
    // residual of open bins consistent, avoiding outlier bin states.
    let dev = (post - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that result in small residuals (tight fit)
    // We penalize large post_residuals exponentially to prioritize filling bins near capacity.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Lookahead: If next_item_size is known, favor bins where the remaining space
    // can accommodate the next item. If next_item_size cannot fit, penalize the current bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating "dead space" that cannot fit the next item
            score += 45.0;
        } else {
            // Reward bins that maintain capacity for the next item
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // 3. Fragmentation Penalty: If fitting_bins_count is 1, this is the last chance for this bin.
    // We avoid opening new bins unless the current fit is extremely inefficient.
    if bin_residual == bin_capacity {
        // This is a new bin. Only pick it if the mean residual is already quite low,
        // suggesting that current bins are too full to accommodate the current item.
        score += 60.0 - (mean_residual * 0.5);
    } else {
        // If we have options, prefer bins that are already closer to the mean residual
        // to keep the bin distribution uniform.
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    // 4. Harmonic Scaling: Penalize bins that leave behind small, unusable slivers (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, be more conservative
    // about opening new bins by increasing the penalty for new bin creation.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

