    }

    // 4. Density balancing: Encourage filling bins that are already "half-empty"
    // relative to the average residual to keep the distribution tight.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Progression scaling: As we approach the end of the stream, 
