    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly or near-perfectly into the post_residual,
    // reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap_after_next = (post_residual - next_item_size) as f64;
            // Reward low-waste pairs; penalize if next item leaves a tiny unusable sliver.
            score -= (100.0 - gap_after_next) * 0.8;
        } else {
            // Penalize if this placement prevents the next item from fitting here.
            score += 20.0;
        }
    }

    // 3. Global Bin Management: Avoid opening new bins unless necessary.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already or if fitting_bins_count is low.
        // Opening a new bin is a last resort; add a large constant penalty.
        score += 45.0 + (open_bins_count as f64 * 2.5);
    } else {
        // If it's an existing bin, reward bins that are closer to the mean_residual
        // to keep the bin distribution uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 4. Progress Sensitivity: As we approach the end of the stream, be more conservative.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
