    // As the stream progresses, prioritize filling existing bins to reduce open_bins_count.
    // We penalize opening new bins (bin_residual == bin_capacity) more heavily as progress increases.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
