    let mut score = post + dead_space_penalty + lookahead_pressure + new_bin_penalty + desperation_bonus;

    // Favor bins that are closer to the mean_residual of the system to maintain uniform packing.
    let deviation_from_mean = (post - mean_residual).abs();
    score += deviation_from_mean * 0.2;

