        }
    }

    // 5. Progression Scaling:
    // As the stream nears the end, become more conservative with bin usage.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Mean Residual Calibration:
    // Penalize bins that are significantly below the mean residual (avoid creating "too full" bins prematurely)
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
