    // Dynamic threshold: As the stream progresses, become more aggressive about 
    // packing tightly to avoid leaving many bins with high mean_residual
    let efficiency_pressure = (mean_residual / bin_capacity as f64) * 100.0;
    score += efficiency_pressure * progress;

    // If this is the only bin that fits the current item, lower the score to prioritize it
    // over opening a new bin (which has post_residual == bin_capacity)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1000.0;
