    // 1. Base cost: Prefer smaller post_residual (Best Fit)
    let mut score = post_residual as f64;

    // 2. Penalize creating a new bin unless necessary
    // If the bin is new (residual == capacity), add a heavy penalty based on how many bins are already open
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead logic: If the next item exists, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin will be unable to accept the next item, penalize slightly
            score += 15.0;
        } else {
            // Reward bins that can accommodate the next item (synergy)
            score -= 10.0;
        }
    }

    // 4. Global state adjustment: If we are late in the stream, prioritize aggressive packing
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late game: prioritize closing bins to reduce total count
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 5. Fitting threshold: Avoid "last resort" bins if they create too much waste
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits, prioritize it strongly
        score -= 50.0;
    }

    // 6. Mean residual balancing: Penalize outliers
    // If this bin's residual is significantly lower than the mean, it's a good candidate (it's "tight")
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining (Best Fit principle)
    // We aim to minimize this to pack bins tightly
    let mut score = post;

    // Penalty for creating 'dead space' (bins with very little room left that cannot fit common items)
    // As progress increases, we become more aggressive about filling gaps.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.5 * (1.0 + progress);
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin to keep the potential for a perfect pair.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // New-bin avoidance: If we are not forced to open a new bin (fitting_bins_count > 0),
    // penalize the "new bin" candidate (where bin_residual == bin_capacity) heavily.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0 + (progress * 40.0);
    }

    // Global state optimization: Penalize opening too many bins early on.
    // If we have many open bins, prioritize closing them by filling them.
    if open_bins_count > 5 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // Non-linear coupling: Favor bins whose residual is closer to the global mean_residual
    // to keep bin levels balanced across the set.
    let dev = (post - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead zones' (small residuals that are hard to fill).
    // Specifically, residuals < 10 are often unusable for the given range (10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next_item_size is known, favor bins that leave enough space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit synergy: reward keeping the bin open for the next item.
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalty if the current placement makes the next item impossible to fit in this bin.
            score += 15.0;
        }
    }

    // Harmonic class logic: penalize placements that result in 'awkward' residuals (e.g., residuals 
    // that are not multiples of common item sizes).
    let harmonic_penalty = (post_residual % 10) as f64 * 1.5;
    score += harmonic_penalty;

    // If this is the only bin that fits the current item, prioritize it to avoid wasting a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New bin bias: Only open a new bin if the current 'best' fit is extremely poor (post_residual is very large).
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, adjusted by how many bins are already open.
        score = 85.0 + (open_bins_count as f64 * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual values 
    // that are too small to fit common items (10-25 range) but > 0.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless the fit is perfect (Best Fit).
    // If this is a new bin, apply a significant penalty scaled by the current open bin count.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Integration: If the next item is large, favor keeping larger residuals open.
    // If current fit is tight, but next item is large, penalize this bin to save space.
    if next_item_size > 60 && post_residual < 40 {
        score += 30.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // provide a slight discount to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Mean Residual Alignment: Penalize bins that deviate significantly from the mean 
    // capacity, preventing the creation of extreme outliers in bin fullness.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins unless necessary (fitting_bins_count > 0)
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0;
    }

    // 2. Best-Fit logic: Prefer smaller post_residual (tighter packing)
    // We already start with post_residual, so we adjust based on lookahead.

    // 3. Lookahead Matching: If post_residual is close to next_item_size, we favor it.
    // We want the remaining space to be exactly enough for the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward if post_residual fits next_item_size, penalize if it leaves a tiny gap
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.5;
        } else {
            score += 50.0;
        }
    }

    // 4. Balance current bin against global average
    // If this bin is much emptier than average, it's a "wasteful" bin.
    if post_residual > (mean_residual as u32) {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Progression scaling: Be more conservative towards the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64 + 1.0);

    // Penalize creating bins with tiny, unusable residuals (dead space between 1 and 9)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we effectively lose potential density.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        } else {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Heuristic for new bin creation:
    // Only open a new bin if the current fit is extremely poor (large residual)
    // or if we are late in the stream and need to clear out space.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if existing ones can fit
            score += 40.0 + (mean_residual * 0.5);
        } else {
            // Must open a new bin
            score = -100.0;
        }
    } else {
        // Favor bins that align with the global mean residual to keep bin states uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Dynamic pressure: as we approach the end of the stream, prioritize tight fits
    score += (1.0 - progress) * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish large post_residuals (Best Fit logic)
    // We aim for post_residual -> 0 (perfect fit).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if is_new_bin {
        // Only open a new bin if we are forced to (fitting_bins_count == 0)
        // or if the stream is nearing the end and we want to consolidate.
        score += 80.0 * (1.0 - progress).powf(0.5);
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Reward filling bins that are already tight to increase density
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 15.0 * tightness;

        // Lookahead: If next item fits in this post_residual, reward it
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Penalize creating "dead space" that is smaller than the smallest likely item
    // If post_residual is in (0, 10), it is very hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Dynamic pressure: as the stream progresses, favor packing into existing bins
    // more aggressively by penalizing the choice of opening new bins.
    score += (open_bins_count as f64).powf(1.2) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small gaps that cannot fit common future items.
    // If post_residual is small (e.g., < 10), it is likely "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual cannot fit the next item, penalize the bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. New Bin Thresholding: Only open a new bin if the current fit is extremely poor 
    // or if the item is large enough that it shouldn't be crowded.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base cost is high, reduced if no other bins fit well.
        score = 45.0 + (open_bins_count as f64 * 0.5);
        if fitting_bins_count > 0 {
            score += 40.0; // Strong resistance to opening new bins if others are available
        }
    }

    // 4. Harmonic Modulo Logic: Reward gaps that are multiples of common item sizes (e.g., 20, 25, 50).
    // This creates "bins of similar items" to maximize future fit probability.
    let remainder = post_residual % 20;
    if remainder == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // 5. Progression Scaling: As the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual to pack tightly, but penalize "fragmentation" 
    // (post_residual < 10) unless it perfectly fills the bin.
    // Also incorporate a pressure mechanism based on open_bins_count and lookahead.

    let mut score = post_residual as f64;

    // Penalty for creating unusable gaps (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Encourage filling bins completely
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: If the next item could fit into this post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Open bin pressure: If we have many open bins, penalize opening a new one heavily.
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If we are nearing the end of the stream, be more conservative about opening new bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 25.0;
    }

    // Balance the mean residual: discourage bins that deviate significantly from the mean
    // to keep the packing density uniform across all active bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // Favor bins that are already "tight" if multiple bins can fit the item
    if fitting_bins_count > 1 && bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating a new bin: only do this if forced or if current bins are very tight.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty for opening a new bin if an existing bin could fit the item.
            score += 150.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Reward opening a new bin if no other options exist.
            score -= 50.0;
        }
    }

    // 2. Lookahead: reward bins where the post_residual matches the next_item_size perfectly.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        if diff == 0.0 {
            score -= 40.0; // Perfect fit for next item
        } else if post_residual >= next_item_size {
            score += diff * 0.5; // Mild penalty for leaving space too large for next
        } else {
            score += 20.0; // Penalty if next item won't fit at all
        }
    }

    // 3. Fragmentation control: penalize residuals that are too small to be useful (1..9 range).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Mean residual balancing: prefer bins that stay close to the average state of the system.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 5. Urgency: as the stream nears the end, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing (BFD) core: 
    // Penalize large post_residuals (wasted space) quadratically.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead utility: 
    // If the next item can fit in the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Fragmentation penalty:
    // If this is the only bin that fits the current item, prioritize it heavily
    // to avoid opening unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // 4. Global Load Balancing:
    // If we are late in the stream, minimize the number of bins by favoring
    // bins that align with the mean_residual of the system.
    if progress > 0.7 {
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    // 5. New Bin Thresholding:
    // If the bin is new (bin_residual == bin_capacity), it is only desirable if 
    // the current item is large or the system is highly fragmented.
    if bin_residual == bin_capacity {
        score += 45.0; // Base cost to open a new bin
        if item_size > 70 {
            score -= 30.0; // Prefer new bin for very large items
        }
        // Penalize new bin if we have many empty/near-empty bins
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best-Fit principle).
    let mut score = post_res;

    // Penalty for creating "slivers" (dead space < 10) which are hard to fill given the input range (10-80).
    // We dampen this penalty as the stream nears completion to allow bin closure.
    if post_residual > 0 && post_residual < 10 {
        score += (15.0 - post_res) * (1.0 - progress * 0.5);
    }

    // Lookahead logic: If the next item is large, favor bins that leave enough room.
    // If next_item_size is 0, we are at the end, so prioritize closing bins (lower residual).
    if next_item_size > 0 {
        let next_fit_pressure = (next_item_size as f64) / (post_res + 1.0);
        score += next_fit_pressure * 5.0;
    } else {
        score -= (100.0 - post_res) * 0.1;
    }

    // Adaptive threshold: As open_bins_count increases, become more aggressive about 
    // using existing bins rather than opening new ones, unless the fit is extremely poor.
    let bin_utilization_factor = (open_bins_count as f64 / (step_index as f64 + 1.0)).sqrt();
    score += bin_utilization_factor * 20.0;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy cost bias
    // that decays as the stream progresses to allow late-stage bin opening.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress.powi(2));
    }

    // Encourage global packing density by penalizing bins that deviate significantly from mean_residual.
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #461: Harmonic-Residual Balancing
    // Strategy: Penalize small fragments that cannot accommodate future items, 
    // while favoring bins that align with the lookahead to keep residuals modular.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64 + 1.0);

    // 1. Reward Best-Fit (Best-Fit Decreasing logic)
    // Minimizing post_residual is the primary driver.

    // 2. Penalty for creating "Dead Zones" (residuals < 10) that are unlikely to fit future items.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 3. Lookahead Alignment: If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item perfectly (Residual == Next)
            score -= 15.0 * (1.0 - (post_residual as f64 - next_item_size as f64).abs() / 100.0);
        } else {
            // Penalize if this placement prevents the next item from fitting
            score += 10.0;
        }
    }

    // 4. Global Density Control: Use open_bins_count to normalize aggressiveness.
    // If we have many open bins, we become more selective (higher penalty for poor fits).
    score += (open_bins_count as f64 * 0.5) * (1.0 - progress);

    // 5. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // Only choose a new bin if the current mean_residual is very low (meaning existing bins are tight).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Essential to open the first bin
        } else {
            // Only open a new bin if current bins are too full to accommodate average expectations
            score = 40.0 + (mean_residual * 0.5);
        }
    } else if fitting_bins_count == 1 {
        // If this is the ONLY bin that fits, prioritize it heavily.
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
