    }

    // 5. Global Efficiency: If the current bin is significantly worse than the mean,
    // penalize it to force the algorithm to gravitate toward uniform bin states.
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmentation" (small gaps that are hard to fill)
    // If post_residual is small but > 0, it's often better to have left it 0 or > 20.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // 2. Lookahead matching: Reward placing the item such that the next_item_size
    // fits perfectly into the remaining space (Best Fit Lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact matches or near-perfect fits for the next item
            let diff = (post_residual - next_item_size) as f64;
            score -= (20.0 / (1.0 + diff)) * 10.0;
        } else {
            // If the next item cannot fit, penalize this bin slightly to favor others
            score += 5.0;
        }
    }

    // 3. Global Bin Management: Prevent creating new bins if existing ones are available.
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can accommodate the item
            score += 45.0 + (fitting_bins_count as f64 * 10.0);
        }
    }

    // 4. Density Balancing: Favor bins that stay near the global mean residual.
    // This helps keep the bin distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Progression Weighting: As we approach the end of the stream, 
    // become more aggressive about filling bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Current progress factor [0.0, 1.0]
    let progress = step_index as f64 / total_items as f64;

    // Base score is the residual space after placement
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large remaining space (post_residual).
    // We already have post_residual as the base, which naturally favors filling bins tightly.

    // 2. Lookahead mechanism: If the next item fits into the post_residual, 
    // prioritize this bin to maximize bin utilization density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0 * (1.0 - progress * 0.5);
    }

    // 3. Scarcity penalty: If this is the only bin that can fit the item, 
    // it is highly valuable; reduce score to ensure we don't open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 4. Global state balance: If current mean residual is high, we are under-utilizing bins.
    // Penalize opening new bins (bin_residual == bin_capacity) if we have plenty of space elsewhere.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.8;
        // Discourage opening new bins too early in the stream
        score += 20.0 * (1.0 - progress);
    }

    // 5. Fragmentation avoidance: If post_residual is very small (e.g., < 10), 
    // it becomes "dead space" that is hard to fill. Penalize these tight fits 
    // unless it is the end of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (1.0 + progress);
    }

    // 6. Dynamic pressure: As the stream nears the end, prioritize finishing off 
    // open bins to minimize the final bin count.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
