}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is likely to be wasted.
    // We penalize these "sliver" gaps heavily unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when existing bins have capacity.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // scaled by how many bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // prioritize it to avoid forcing a new bin allocation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: If the bin is becoming very tight (e.g., < 5 space), 
    // treat it as a "closing" bin to maximize packing density.
    if post_residual < 5 {
        score -= 10.0;
    }

    // 6. Distributional Smoothing: Adjust based on how full the bin is relative to the mean.
    // This helps keep bin utilization consistent across the set of open bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (fill_ratio - (1.0 - (mean_residual / bin_capacity as f64))) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
