        }
    }

    // 6. Progress-based scaling: As we reach the end of the stream, be more conservative
    // about leaving empty space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals to keep bins tightly packed.
    // However, we apply a non-linear weight to favor very tight fits (post_residual < 10).
    if post_residual < 5 {
