    // Avoid creating bins that deviate significantly from the current mean_residual.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Fragmentation control: 
    // Penalize bins that leave behind "unusable" space (too small for most items).
    // Given items are 1-100, residuals < 10 are often dead zones.
    if post_residual > 0 && post_residual < 10 {
