    }

    // Multi-bin pressure:
    // If we have many open bins, penalize opening a new one further.
    // If we have very few, reward creating a new one if the fit is perfect.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).sqrt() * 5.0;
    }

    // Interaction with mean_residual:
    // Avoid creating bins that are significantly below the current average efficiency.
    if post < mean_residual * 0.5 {
        score += 15.0;
    }

    // Final scaling: favor placements that maintain high density.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
