    // If post_residual is between 1 and 9, it is highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits better in this bin than the current one, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bins Pressure: Penalize opening new bins unless necessary.
    // If bin_residual == bin_capacity, we are evaluating the cost of a new bin.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the number of currently open bins is low,
        // or if fitting_bins_count is 0 (forced).
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Preference for new bin when forced
        }
    }

    // 4. Compactness Bias: Prefer bins that are already well-filled (lower mean_residual).
    // This encourages "Best Fit" behavior to keep the mean_residual low.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // 5. Final adjustment based on stream progression:
    // As we approach the end, be more aggressive about packing tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
