    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // Time horizon: In the final stages of the stream, prioritize aggressive packing 
    // to reduce the total bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // Penalize creating "dead space" (e.g., small residuals that are unlikely to fit future items).
