    // We penalize bins that leave a post_residual too small for the next item, 
    // unless the current item perfectly fills the bin.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Penalize leaving a "dead" gap that cannot fit the next predicted item.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. Fragmentation Mitigation:
    // If the post_residual is very small (e.g., < 10), it is likely "junk" space.
    // We penalize small residuals to encourage packing that leaves room for larger items.
    if post_residual > 0 && post_residual < 15 {
        score += 20.0;
    }

    // 4. Density Balancing:
    // If we have many open bins, prioritize packing into bins that are already 
    // "nearly full" to increase the chance of closing them.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // 5. Last Chance Heuristic:
    // If fitting_bins_count is 1, this is the only bin that can take this item.
    // Strongly reward taking it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progressive Tightening:
    // As the stream nears the end, become more aggressive in packing to minimize final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
