    // Penalty for creating a 'fragment' that is too small to fit common items (10-30).
    // The penalty is non-linear, peaking at a residual of ~15, and tapering off as we approach 0.
    let fragmentation_penalty = 50.0 * (-(post - 15.0).powi(2) / 100.0).exp();
    score += fragmentation_penalty;

    // Reward for matching the next item size (Lookahead optimization).
    // If post_residual is close to next_item_size, we reduce the score to prioritize this bin.
    if next_item_size > 0 {
        let diff = (post as f64 - next_item_size as f64).abs();
        score -= 25.0 * (-diff / 10.0).exp();
    }

    // Adaptivity: As the stream progresses, prioritize tighter packing (lower residuals).
    // We penalize opening new bins more heavily as total_items approaches, 
    // unless the current bin is nearly empty.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress and the mean_residual of existing bins.
        // If existing bins are already tight (low mean_residual), opening a new bin is penalized more.
        score += 45.0 + (progress * 30.0) + (mean_residual * 0.5);
    } else {
        // Reward for keeping bins consistent with the current mean residual.
        score += (post - mean_residual).abs() * 0.2;
    }

    // Critical constraint: If this is the only bin that fits, we force it by lowering the score.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
