        // to keep bin utilization balanced.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Non-linear coupling: Exponentially punish very large residuals late in the stream
    // to force packing tighter as we approach the end of the item set.
    score += (post / capacity).powf(2.0) * progress * 50.0;

