    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that are significantly emptier than the average open bin.
    if post_residual > mean_residual as u32 {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // 5. Last-chance logic:
    // If this is the only fitting bin, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
