    let mut score = post_residual as f64;

    // 2. Penalty for creating unusable space:
    // If the post_residual is smaller than the smallest possible item (10), 
    // it is often "dead space". We penalize this heavily unless it reaches exactly 0.
    if post_residual > 0 && post_residual < 10 {
