    }

    // 4. Global State Balancing:
    // As the stream progresses, we become more conservative about opening new bins.
    // We penalize opening new bins more heavily as total_items approaches.
    if is_new_bin {
        // High base cost for opening a new bin
        score += 45.0;
        // Increase penalty based on progress to favor packing into existing bins late-game
        score += 30.0 * progress;

        // If we have many open bins already, don't open another unless necessary
        score += (open_bins_count as f64) * 2.0;
    } else {
        // Reward packing into bins that are already "fuller" than the average to keep 
        // the mean_residual low (defragmentation)
        if (bin_residual as f64) < mean_residual {
