    // unless the current open bins are very full.
    if bin_residual == bin_capacity {
        // Penalty scales with how much space is left in existing bins.
        // If mean_residual is low, we are crowded; opening a new bin is better.
        score += 40.0 - (mean_residual * 0.4);
    }

    // Smooth non-linear coupling: penalize bins that deviate significantly 
    // from the mean residual of the system to maintain uniform packing.
    let residual_deviation = (post_res - mean_residual).abs();
    score += 0.1 * residual_deviation.powf(1.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
