pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small, unusable residues (1..9)
    // which are likely to remain empty for the rest of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Best-Fit Bias: Encourage filling bins as tightly as possible.
    // We favor bins where the post_residual is small, but not so small it's useless.
    // If post_residual is 0, it's a perfect fit (rewarded).
    if post_residual == 0 {
        score -= 20.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when current ones are available.
    // Only open a new bin if the current fit is extremely poor (large post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High cost to open a new bin proportional to how many are already open.
        score += 40.0 + (open_bins_count as f64 * 2.5);
    } else {
        // Reward using existing bins, scaled by how much space we save.
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 4. Lookahead Integration: If the next item fits into the remaining post_residual,
    // prioritize this bin to prepare for a "combo" placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
    }

    // 5. Scarcity/Fitting constraint: If this is the only bin that fits, we must take it
    // unless the fit is absolutely terrible (dead space).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Aggressive 2-step lookahead matching.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // This naturally favors Best-Fit.

    // 2. Lookahead Coupling: If next_item_size fits in the post_residual, 
    // significantly reward this placement to chain items together.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 50.0 + (next_item_size as f64 * 0.5);
    }

    // 3. Fragmentation Avoidance: If post_residual is small but > 0, it creates "dead space"
    // that is hard to fill. Penalize small remainders unless they are 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global Density Control: If fitting_bins_count is 1, we are at a decision point.
    // If the new bin candidate (is_new_bin) is being evaluated, penalize it 
    // unless the current mean_residual is very high (indicating existing bins are poorly used).
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Discourage opening a new bin if we have space elsewhere.
            score += 60.0;
        }
        // If current bins are already very full (low mean_residual), 
        // it is safer to open a new bin rather than packing into tight space.
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // 5. Progression Scaling: As the stream nears the end, become more aggressive 
    // in closing bins by prioritizing tighter fits (reducing the penalty for fragmentation).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize tiny residuals (the "fragmentation trap")
    // We heavily penalize residuals < 10, as they are often useless for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // we reward this placement to keep the bin tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / 100.0);
    }

    // 3. Global State Awareness: If we have many open bins, we become more "picky"
    // about opening a new bin, making the new-bin option more expensive.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5) + (progress * 15.0);
    }

    // 4. Fitting Pressure: If this is the only bin that fits the current item,
    // we reward placing it here to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Dynamic Mean Balancing: Avoid bins that are significantly less full than the average,
    // as they indicate poor packing density.
    let bin_used = bin_capacity - bin_residual;
    let mean_used = bin_capacity as f64 - mean_residual;
    if (bin_used as f64) < mean_used {
        score += 5.0 * (mean_used - bin_used as f64) / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": residuals that are too small to fit typical future items.
    // We penalize post_residual values that are between 1 and 9 (highly likely to be wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if the next item cannot fit in this bin, penalize the current choice 
    // to preserve capacity for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - progress);
    }

    // Dynamic thresholding: As we reach the end of the stream, prioritize closing bins
    // by heavily penalizing opening new bins unless the fit is perfect.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We make it expensive early on, but cheaper as we run out of space in existing bins.
        score += 40.0 * (1.0 - progress) + (open_bins_count as f64 * 0.5);
    } else {
        // If this bin is the last chance for the current item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Coupling with mean_residual: If this bin is significantly emptier than the average,
    // it is a better candidate to absorb the item to keep the distribution uniform.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (gaps < 10 are usually impossible to fill)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Best-fit principle: prefer bins that leave the smallest residual (already captured by post_residual)
    // but penalize the use of a new bin unless the remaining space is extremely constrained
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 45.0; // Heavy penalty for opening new bin if others can fit
        }
    }

    // Lookahead logic: if next_item fits in the current post_residual, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // Harmonic alignment: prioritize filling bins to specific thresholds (e.g., 20, 25, 33, 50)
    // This reduces fragmentation by keeping residual space in "useful" chunks
    let remainder_mod = post_residual % 20;
    if remainder_mod == 0 {
        score -= 10.0;
    }

    // Global load balancing: if we have many bins, be more aggressive about filling existing ones
    // even if the fit is slightly suboptimal
    if open_bins_count > 5 {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // Final adjustment based on stream progression: as we near the end, prioritize closure
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating unusable gaps (Dead Space Avoidance)
    // Small gaps (1..9) are extremely hard to fill given the input range (10..80)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Lookahead logic: if the next item doesn't fit, prioritize bins that keep 
    // the current bin's residual large enough to accommodate future items.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that leave a gap too small for the next expected item
            score += 20.0;
        }
    }

    // Open bin pressure: discourage opening too many bins early in the stream.
    // If this is a new bin, apply a dynamic cost based on progress.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.0 * (1.0 - progress));
    }

    // If this is the last fitting bin, prioritize it to avoid opening a new bin
    // unless the post_residual is critically small (dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Favor bins that align with the global mean residual to keep packing density uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We prioritize bins that leave the least space (Best-Fit principle).

    // 2. Lookahead Synergy: If the next item fits perfectly in the post_residual, 
    // heavily reward this bin (making the score very low/negative).
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_gap).powf(1.5);
    }

    // 3. New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // only accept it if the current fitting options are extremely poor.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            return -1000.0; // Must open if empty
        }
        // Only open a new bin if the mean residual of existing bins is already tight (< 15)
        // or if there is no other bin that can fit the item.
        if mean_residual > 15.0 && fitting_bins_count > 0 {
            score += 500.0; // Heavily penalize opening a new bin unnecessarily
        }
    }

    // 4. Distributional Balancing: If fitting_bins_count is 1, this is the last chance
    // for this item before a new bin is forced. Prioritize this bin to avoid fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Progress Normalization: As the stream nears the end, become more aggressive 
    // about filling bins to reduce the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is too empty to be useful later
    if post_residual > 60 {
        score += 50.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Best-Fit Decreasing logic: heavily favor tight fits
    score += (post_residual as f64).powf(1.5);

    // Lookahead logic: if next_item fits in the current post_residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // Global state awareness: if we are near the end of the stream, prioritize closing bins
    // by penalizing empty space more aggressively
    if progress > 0.8 {
        score += post_residual as f64 * 2.0;
    }

    // New bin logic: if we have multiple fitting bins, penalize opening a new one
    // unless the current residual is very large (highly inefficient)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening new bins if there are existing candidates
            score += 40.0 + (fitting_bins_count as f64 * 10.0);
        } else {
            // If no bins fit, opening a new one is necessary, but we penalize it
            // based on how much the current item size deviates from the mean
            score += (item_size as f64 - mean_residual).abs();
        }
    }

    // Interaction between mean_residual and current fit
    // If our post_residual is much lower than the mean, we are creating a tight bin
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit preference).
    let mut score = post;

    // Penalty for opening a new bin prematurely: 
    // If the bin is new, scale the penalty by the remaining stream length.
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64 * 0.75) * (1.0 - progress);
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // prioritize this bin to reduce fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.6;
    }

    // Dynamic penalty for creating "dead space":
    // If post_residual is small but > 0, it's often better to leave it empty 
    // than to trap a small remainder that cannot fit common items.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 + progress);
    }

    // Coupling with mean_residual: 
    // If this bin's post_residual is significantly better than the global mean, 
    // reward the choice to keep the bin profile consistent.
    if post < mean_residual {
        score -= (mean_residual - post) * 0.4;
    }

    // Penalize the creation of many bins if the stream is nearing completion.
    if fitting_bins_count == 0 && progress > 0.8 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "fragmentation" (dead space < 10):
    // Small residuals are usually hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic Lookahead: If next item fits in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Harmonic Class Logic: Reward placements that leave "round" residuals (multiples of 20 or 25).
    // These fractions (1/4, 1/5 of capacity) are highly versatile for future fits.
    if post_residual % 20 == 0 {
        score -= 10.0;
    } else if post_residual % 25 == 0 {
        score -= 8.0;
    }

    // 4. New Bin Strategy: If current bin is empty (bin_residual == bin_capacity), 
    // only open it if no other fitting bins exist (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0; // Heavy penalty to prevent opening new bins unnecessarily
        } else {
            score -= 50.0; // Force opening when no other options exist
        }
    }

    // 5. Density Balancing: If we have many open bins, penalize larger post_residuals 
    // to encourage packing tightly into existing bins.
    if open_bins_count > 3 {
        score += (post_residual as f64) * 0.5;
    }

    // 6. Progressive Tightening: As we approach the end of the stream, 
    // prioritize lower post_residuals more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small gaps that are unlikely to fit future items.
    // If post_residual is in the range [1, 9], it is high-risk for becoming "stranded" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Synergy: If the next item can fit in the remaining space, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when existing bins have capacity.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty based on open bin count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // Discourage new bin usage if other bins are underutilized.
        if mean_residual > 30.0 {
            score += 40.0;
        }
    }

    // 4. Fitting Scarcity: If this is the only bin that can fit the current item, 
    // prioritize it to avoid forced new bin allocation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Final refinement: Favor tighter fills (lower post_residual) generally, 
    // but normalize against the mean residual to maintain balance.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common item sizes)
    // Residuals < 10 are often unfillable given the item distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // If next_item_size fits perfectly into the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        // The closer the fit to zero, the better the packing
        score -= (50.0 - fit_diff).max(0.0) * 1.5;
    }

    // 3. Balance against mean_residual:
    // Avoid creating bins that are significantly emptier than the average open bin.
    if post_residual > (mean_residual as u32) {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 4. New bin management:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // proportional to the number of bins already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.2);
    }

    // 5. Last-chance optimization:
    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bin allocation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progression factor:
    // As the stream nears completion, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post-residuals (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one fits
            score += 45.0 + (progress * 20.0);
        } else {
            // Baseline for when we actually need a new bin
            score = 10.0;
        }
    } else {
        // Evaluate lookahead: If next item fits in the current post_residual, reward this placement
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }

        // If this bin is the last one that can fit the current item, prioritize it
        if fitting_bins_count == 1 {
            score -= 5.0;
        }

        // Global state heuristic: Avoid creating "sliver" residuals (1-9) which are hard to fill
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Dynamic thresholding: As we approach the end of the stream, prioritize packing tighter
        if progress > 0.8 {
            score += (post_residual as f64) * 0.5;
        }
    }

    // Adjust based on the mean residual of the system to maintain balance
    // If our bin is significantly emptier than the average, penalize placing here to consolidate
    if (bin_residual as f64) > mean_residual * 1.2 {
