}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize large empty spaces (dead space) quadratically
    // The exponent 1.5 helps prioritize tighter fits while avoiding extreme values
    let fit_penalty = post.powf(1.5);

    // Lookahead interaction: penalize creating a post-residual that cannot fit the next item
    // If next_item_size is 0 (end of stream), this term is neutral
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_residual as f64) * 2.0
    } else {
        0.0
    };

    // New bin bias: if we are early in the stream, be more conservative about opening new bins.
    // If late in the stream, be more aggressive to consolidate remaining items.
    let new_bin_bias = if bin_residual == bin_capacity {
        (1.0 - progress) * 15.0 + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Favor bins that align with the current mean_residual to keep bin distribution uniform
    let uniformity_bonus = (post - mean_residual).abs() * 0.1;

    // Critical constraint: If this is the only bin that fits, prioritize it heavily
    let urgency_factor = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -20.0
    } else {
        0.0
    };

    fit_penalty + lookahead_penalty + new_bin_bias + uniformity_bonus + urgency_factor
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
