            let slack = post_residual - next_item_size;
            if slack < 5 {
                score -= 15.0;
            }
        }
    }

    // 4. Density Balancing: If we have many open bins, penalize opening a new one 
    // unless the residual is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 {
            score += 30.0 + (open_bins_count as f64 * 2.0);
