            score -= 40.0 * (1.0 / (1.0 + diff));
        } else {
            // Penalize if the next item won't fit in this bin
            score += 20.0;
        }
    }

    // 3. Pressure management: If few bins fit the current item, prioritize using them
    if fitting_bins_count == 1 && bin_residual >= item_size {
