    }

    // 4. Global state coupling: Encourage keeping the average residual low across the bins
    // to prevent fragmenting space too early in the stream.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 10.0;
    }

    // 5. Progression adjustment: As the stream nears the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

