        // Only open a new bin if we have many items left or if fitting_bins_count is zero.
        if fitting_bins_count > 0 {
            score += 60.0 * (1.0 - progress);
        } else {
            score -= 10.0;
        }
    }

    // 4. Global Load Balancing: Avoid fragmenting bins when many are open.
    // Penalize bins that deviate significantly from the mean residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Urgency factor: As we approach the end of the stream, prioritize closing bins.
    if progress > 0.9 {
        score -= (bin_capacity - post_residual) as f64 * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Best Fit (minimize post_residual)
    let mut score = post_res;

    // Penalty for creating "dead space": residual space that is too small to fit typical future items.
    // If post_residual is small but > 0, it is often worse than a perfect fit (0).
    // We apply a non-linear penalty for small residuals (1..10) which are often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead coupling: If the next item fits into the current post_residual, 
    // reward this bin choice to encourage bin packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Stream progression adjustment:
    // As we approach the end of the stream (progress -> 1.0), prioritize clearing existing bins 
    // (lowering mean_residual) to avoid opening new bins unnecessarily.
    if progress > 0.5 {
        score += (mean_residual * 0.5) * (progress * progress);
    }

    // Heuristic for new bin candidate (bin_residual == bin_capacity):
    // Only open a new bin if the current fit is extremely poor (post_residual is very large)
    // or if we have very few open bins and the current items are large.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base cost is high.
        score = 80.0;
        // Reduce penalty if current bins are already very full (mean_residual is small).
        if mean_residual < 20.0 {
            score -= 30.0;
        }
        // Reduce penalty if this is the only way to fit a large item effectively.
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // Final normalization: prefer bins that are already partially filled to pack them tighter.
    score -= (open_bins_count as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (residuals < 10 are hard to fill)
    if post_residual > 0 && post_residual < 10 {
