    }

    // Lookahead logic: If the next item could fit perfectly into the post_residual, 
    // reward this placement highly.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs();
        if diff == 0 {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Reward bins that maintain room for the next item without being too wasteful
            score -= 10.0 * (1.0 - (diff as f64 / bin_capacity as f64));
        }
    }

    // Heuristic for new bin creation:
    // Only open a new bin if the current fit is extremely poor (large post_residual) 
    // or if we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin prematurely
            score += 60.0;
        } else {
            // Neutral score for forced new bin
            score = 0.0;
        }
    }

    // Balance against global state: if mean_residual is high, we are currently 
    // wasting space, so prioritize filling bins that are already partially full.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Progress-based scaling: as the stream nears the end, become more aggressive 
    // about packing tightly to avoid new bin creation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
