    let post = post_residual as f64;

    // Penalize small residuals (dead space) more heavily as the stream progresses, 
    // favoring tight fits early and flexible bins late.
    // Exponential term creates a "valley" for optimal residual sizes.
    let base_score = post.powf(1.5) + (100.0 - post).exp() * 0.01;

    // Penalty for opening new bins: if this is an empty bin (bin_residual == bin_capacity),
    // apply a cost that scales with progress to prevent premature fragmentation.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
