    // If this bin is significantly emptier than the average, penalize it slightly 
    // to favor filling up already "crowded" bins first.
    let load_balancing = if bin_residual > (mean_residual as u32) {
        (bin_residual as f64 - mean_residual) * 0.5
    } else {
