    // If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Bonus for "perfect" fits (residual becomes 0)
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. Fragmentation Avoidance:
    // If this is the only bin that fits the current item (fitting_bins_count == 1),
    // heavily incentivize using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // 4. Capacity Distribution:
    // Discourage creating bins with very low residual if many bins are open.
    // This pushes the algorithm towards Best-Fit behavior when many bins exist.
    if open_bins_count > 5 {
        score += (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 5. New Bin Thresholding:
    // If bin_residual == bin_capacity, this is a new bin.
    // Only open a new bin if the score is significantly better than existing options.
    if bin_residual == bin_capacity {
        // High base penalty for opening a new bin;
        // reduce penalty if many items are remaining to allow density optimization.
        let progress = step_index as f64 / total_items as f64;
        score += 45.0 + (progress * 15.0);
    }

    // 6. Mean Residual Balancing:
    // If this bin is significantly worse than the average, penalize it.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We define "unusable" as < 10 (minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if the next item doesn't fit in the remaining space, 
    // prioritize keeping this bin "flexible" (higher post_residual) 
    // unless this is the only bin that fits the current item.
    if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
