    // Pressure factor: if we have many bins open, penalize opening a new one 
    // or picking a bin that leads to fragmented space.
    let bin_pressure = open_bins_count as f64 * 0.5;

    // If this is a new bin (bin_residual == bin_capacity):
    // Heavily penalize opening a new bin unless the current residual environment is poor.
    if bin_residual == bin_capacity {
