        if open_bins_count > 5 {
            score += 40.0;
        }
    } else {
        // Reward bins that bring the residual closer to the global mean, 
        // promoting uniform packing density.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Critical constraint: If this is the last chance to fit an item, 
    // reduce the score to ensure it is picked over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
