    // we become more aggressive about filling existing bins (minimizing open_bins_count).
    // We penalize opening new bins (bin_residual == bin_capacity) more heavily as progress increases.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 + progress.powf(2.0));
    }

    // Balancing load:
    // Penalize bins that deviate significantly from the mean_residual to keep bin states uniform.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    // Criticality heuristic:
    // If this is the only bin that can fit the item, prioritize it heavily by reducing the score.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
