    // Penalize empty bins significantly based on stream progress to encourage consolidation.
    let mut score = post_res.powf(1.5);

    // If this is a new bin, apply a progress-dependent penalty.
    // Early in the stream, we are more lenient with new bins; late in the stream, we are strict.
    if bin_residual == bin_capacity {
