        score -= (100.0 - post_res) * 0.5;
    }

    // Global density adjustment: penalize configurations that deviate significantly 
    // from the mean residual of active bins to encourage uniform bin filling.
    let residual_diff = (post_res - mean_residual).abs();
    score += residual_diff * 0.2;

