    // but favor tight fits (post_residual near 0).
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Lookahead: If next_item_size is large, avoid small post_residuals
    // that effectively "trap" space too small for the upcoming item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 3. Penalty for fragmentation: If post_residual is in the "dead zone" (1..9),
    // it's unlikely to fit future items. Penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. New Bin Thresholding: If this is an empty bin (new bin candidate),
    // only choose it if the current best existing bin is extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 45.0 + (mean_residual * 0.2);

        // If we are late in the stream, favor closing bins rather than opening new ones
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Fitting constraint: If this is the only bin that fits, prioritize it
    // to prevent unnecessary bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Harmonic Class Balancing: Favor bins where the residual matches 
    // common item divisors (e.g., 20, 25, 33, 50).
    if post_residual > 0 {
        let harmonic_penalty = (100.0 / post_residual as f64).ln() * 2.0;
        score += harmonic_penalty;
    }

    score
