    // and the post_residual is very high (meaning a bad fit), we increase the score to 
    // potentially favor opening a new bin (if the new bin's score is lower).
    if fitting_bins_count == 1 && post_residual > 40 {
        score += 35.0;
    }

    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly from the current mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Empty Bin Handling: The score for a brand-new bin (bin_residual == bin_capacity)
    // is fixed here to act as a threshold. We want to be selective about opening new bins.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low (suggesting we are tight)
        // or if we are early in the stream.
        score = 65.0 - (mean_residual * 0.3);
    }

    score
