        }
    }

    // Interaction with mean_residual:
    // If this bin's post_residual is significantly worse than the current mean, 
    // add a penalty to encourage packing into better-performing bins.
    if post_res > mean_residual {
        score += (post_res - mean_residual) * 0.5;
    }

