    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. New bin handling:
    // Only open a new bin if the mean_residual is very tight (implying we need more room)
    // or if the current item is large and would leave an awkward gap in existing bins.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -1000.0; // Must open if no bins exist
        } else if mean_residual > 30.0 {
            score += 20.0; // Discourage new bins if we have plenty of open space
        } else {
            score += 60.0; // General penalty for opening new bins
        }
    }

    // 6. Progress scaling:
    // As we reach the end of the stream, prioritize packing tighter.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // The core objective is to minimize post_residual (Best Fit), but we apply 
    // non-linear penalties to avoid fragmenting space in a way that prevents 
    // future items from fitting.

    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (leftover space too small for any likely item)
    // We penalize post_residual heavily if it's small but not zero (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if we know the next item, prioritize bins that can 
    // accommodate the next item after the current one.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        } else if post_residual > 0 {
            // Penalty if we block the next item from fitting in this bin
            score += 10.0;
        }
