    // Heuristic for opening a new bin: only open if the current fit is terrible
    // or if we are nearing the end of the stream and need to consolidate.
    if is_new_bin {
        // Only consider a new bin if we have many bins open and the current 
        // options for existing bins are all "poor" (high post_residual).
        if open_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        } else {
            score = 0.0;
        }
    } else {
        // Reward filling bins that are already partially full (reduce open_bins_count)
        score -= (bin_capacity - bin_residual) as f64 * 0.1;

        // If this is the only bin that can fit the item, prioritize it highly
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // Dynamic horizon: as we approach the end of the stream, prioritize 
    // tighter packing over bin count.
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
