        }
    }

    // Encourage packing into bins that bring the mean residual closer to the
    // average size of items to ensure high bin utilization.
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * 0.5;

    // If this is a brand new bin (bin_residual == bin_capacity), apply a heavy 
    // penalty that decays as the stream progresses, but is heavily gated by 
    // the number of available fitting bins.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive. We only do it if the fitting bins 
        // offer significantly worse utilization (high score).
        let new_bin_base_cost = 45.0; 
        score = new_bin_base_cost * (1.0 - (progress * 0.3));

        // If we have other bins that can fit the item, exponentially increase 
        // the cost of opening a new one to prevent fragmentation.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).powf(1.5) * 20.0;
        }
    } else {
        // For existing bins, reward fitting the item into a bin that is 
        // already 'tight' to keep others empty.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
