    // 6. Mean Residual Balancing:
    // Encourage placing items in bins that are closer to the current average fullness
    // to prevent "fragmentation" (having some very empty and some very full bins).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
