    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 4. Scarcity/Efficiency weighting
    // Penalize opening new bins unless necessary (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one is available
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Neutral score for forced new bin
            score = 30.0;
        }
    }

    // 5. Progression scaling: As we reach the end of the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is likely unusable.
    // Penalize heavily to push items into bins where they fit perfectly or leave larger gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Open Bins Pressure: If we are deep in the stream, penalize opening new bins.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Increase penalty for opening new bins as the stream progresses.
        score += 40.0 + (progress * 60.0);

        // If there are bins that can fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 3. Lookahead Logic: If the next item is large, prefer leaving space in the current bin.
    // Specifically, if next_item_size is large and post_residual is small, we are "trapping" the bin.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 4. Consolidation: Favor filling bins that are already "below average" in residual
    // to keep the number of active bins from fragmenting.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space to keep bins tight.
    // However, if bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual < bin_capacity {
        // Favor tighter fits (smaller post_residual).
        score += post_residual as f64 * 0.5;

        // 2. Lookahead matching: If the next item fits perfectly in the remaining space, 
        // prioritize this bin heavily to prevent fragmentation.
        if next_item_size > 0 && post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            // Reward bins that leave exactly enough room for the next item.
            score -= (100.0 - diff) * 2.0;
        }

        // 3. Last-chance logic: If this is the only bin that fits the item, 
        // we must avoid opening a new bin unless the current fit is catastrophic.
        if fitting_bins_count == 1 && post_residual > 40 {
            score += 50.0;
        }
    } else {
        // Penalize opening a new bin if other options exist.
        // We make the score of a new bin dependent on how many bins are already open 
        // and the current mean residual to avoid premature bin opening.
        score = 80.0 + (open_bins_count as f64 * 0.5) - (mean_residual * 0.2);
    }

    // 4. Global progress adjustment: As we near the end of the stream, 
    // become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 40.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // The base score is already post_residual, which naturally favors Best-Fit.

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // reward this bin to keep the next item's space available.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 - progress);
    }

    // 3. Global State: If we have many open bins, penalize opening a new one heavily.
    // If we have very few, be more lenient to avoid fragmented bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + (open_bins_count as f64 * 2.5);
    }

    // 4. Tightness Threshold: If this bin is the only one that can fit the item (fitting_bins_count == 1),
    // and the post_residual is very small (e.g., < 5), we risk creating "dead space."
    // We penalize this slightly to encourage using a different bin if one exists.
    if fitting_bins_count == 1 && post_residual < 5 && post_residual > 0 {
        score += 15.0;
    }

    // 5. Dynamic Horizon: As we reach the end of the stream, prioritize closing bins
    // over maintaining perfect residual balance.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 6. Mean Residual Balancing: Prevent individual bins from deviating too far from the mean.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

