    let mut score = post;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it is often worse than 0 (perfect fit).
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (1.0 - post / 10.0);
    }

    // Lookahead logic: if we know the next item, penalize leaving a residual smaller than it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 25.0 * (1.0 + (next_item_size as f64 - post) / 100.0);
        }
    }

    // Dynamic pressure: as the stream progresses, favor packing tighter to close bins.
    // We penalize opening new bins (bin_residual == bin_capacity) more as progress increases.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 + progress);

        // If we have many bins open, discourage opening a new one unless necessary.
        score += open_bins_count as f64 * 2.0;
    } else {
        // Reward bins that have a residual close to the mean, promoting balanced filling.
        let deviation = (post - mean_residual).abs();
        score -= 5.0 * (1.0 - (deviation / bin_capacity as f64));
    }

    // If this is the only bin that fits, prioritize it strongly to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
