        }
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins (lower residual)
    // to prevent fragmentation.
    score += (open_bins_count as f64) * (1.0 + progress * 2.0);

    // If this is a new bin, apply a threshold penalty based on how many 
    // existing bins could have accommodated the item.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if other options exist.
        // The penalty scales down as the stream progresses to allow for better packing 
        // in the final stages where fragmentation is unavoidable.
        score += 35.0 * (fitting_bins_count as f64).sqrt() * (1.1 - progress);
    } else {
        // Reward bins that bring the mean residual closer to a target density.
        // We want to keep the mean residual low.
        score += (post - mean_residual).abs() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

