    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Harmonic/Fractional distribution:
    // Favor bins that align with the mean_residual to keep load balanced across bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 6. Final adjustment for scarcity:
    // If fitting_bins_count is 1, this bin is the only option; reduce score to ensure it is picked.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
