}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating "dead space" (small residuals that are unlikely to fit future items)
    // We penalize residuals in the [1, 9] range heavily, as items are >= 10.
    if post > 0.0 && post < 10.0 {
        score += 50.0 / post;
    }

    // Lookahead logic: If we have a next item, favor bins that can fit both current and next.
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= 15.0 * (1.0 - progress);
