    // Dynamic thresholding: Near the end of the stream, prioritize closing bins over opening new ones.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalize opening a new bin heavily if other bins could fit the item.
        score += 25.0 + (fitting_bins_count as f64 * 10.0);

        // As we approach the end of the stream, it becomes more expensive to open new bins.
        score += progress * 40.0;
    }

    // Interaction with mean_residual:
    // If the current bin's post_residual is significantly better than the global average, reward it.
    let residual_diff = mean_residual - post;
    score -= residual_diff * 0.5;

    // Favor bins that are "almost full" to consolidate space (Best Fit variant)
    // The term (bin_capacity - post) is the filled space; higher is better.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
