    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If a future item fits into the current post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item
            score -= 25.0;
        } else {
            // Penalize if this placement prevents the next item from fitting
            score += 15.0;
        }
    }

    // 3. Global bin pressure: 
    // Penalize opening new bins heavily as the stream progresses.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // The base cost to open a new bin is high.
        score += 40.0;
        // Increase pressure to consolidate as we approach the end of the stream
        score += (step_index as f64 / total_items as f64) * 30.0;
    } else {
        // Encourage using existing bins that have a residual similar to the mean
        let diff = (bin_residual as f64 - mean_residual).abs();
        score -= diff * 0.1;
    }

    // 4. Scarcity heuristic: 
    // If this is the only bin that fits the item (fitting_bins_count == 1),
    // prioritize it to avoid potentially forcing a new bin later.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual
    // This is already the base score.

    // 2. Lookahead Synergy: If the post_residual can fit the next item, heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
        // Further reward if it creates a near-perfect fit for the next item
        let gap = post_residual - next_item_size;
        score -= (100.0 / (gap as f64 + 1.0));
    }

    // 3. Penalty for opening new bins: Only open a new bin if the current fit is terrible (high post_residual)
    // or if the mean residual is already quite low (suggesting we are packing tightly).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            // Heavily penalize opening a new bin if we have existing capacity
            score += 60.0;
        } else {
            // Otherwise, neutral to slightly positive for new bins
            score += 10.0;
        }
    }

    // 4. Fitting constraints: If this is the only bin that fits the current item, 
    // it must be prioritized to avoid being forced into a new bin later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression awareness: As we near the end of the stream, prioritize closing bins
    // by rewarding smaller residuals more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalize large gaps that are too small for common items (Best-Fit Decreasing intuition)
    // Small post_residuals are generally good, but if they are < 10, they are often "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Global State: If we have many open bins, penalize opening a new one (high cost of fragmentation).
    // If bin_residual == bin_capacity, we are evaluating the cost of starting a fresh bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (progress * 20.0);
        }
    } else {
        // If the bin is already open, favor it more as the stream progresses to consolidate.
        score -= (progress * 15.0);
    }

    // Fitting density: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean residual balance: Avoid bins that deviate significantly from the average state.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement. 
    // We want to minimize this (Best Fit strategy).
    let mut score = post_res;

    // Penalty for creating a bin that is too "tight" (leaving small, unusable gaps < 10)
    // as the stream progresses, these small gaps become harder to fill.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // we heavily favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // If this is the only bin that fits, we are forced to use it.
    // Otherwise, penalize the creation of a new bin based on progress.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Discourage opening new bins early if existing bins can take the load.
            score += 40.0 * (1.0 - progress * 0.5);
        } else {
            // If no existing bin fits, we must open a new one; keep score neutral.
            score += 5.0;
        }
    }

    // Balance the distribution of residuals across open bins to prevent 
    // having too many bins with high residuals (approaching mean_residual).
    if post_res > mean_residual {
        score += (post_res - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_res) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize configurations that leave very small, unusable remainders.
    // Small remainders (< 10) are rarely useful for future arrivals (10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Class Logic: Favor bins that leave space matching typical item size clusters.
    // If post_residual is near 50, 33, or 25, it aligns with harmonic divisions of 100.
    let harmonic_penalty = ((post_residual as f64 % 25.0) - 12.5).abs();
    score += harmonic_penalty * 0.5;

    // 3. Lookahead Integration: If the next item is large, prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0; // Reward bins that can fit the next item
        } else {
            score += 15.0; // Penalize bins that would force a new bin for the next item
        }
    }

    // 4. Density Balancing: Avoid opening new bins unless necessary.
    // If bin_residual == bin_capacity, we are evaluating a NEW bin.
    if bin_residual == bin_capacity {
        // High penalty to prevent opening new bins when current ones have space.
        score += 40.0 + (open_bins_count as f64 * 2.0);

        // If we are at the end of the stream, prioritize closing existing bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // Reward filling existing bins to keep open_bins_count low.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Fitting Constraint: If this is the last bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize gaps that are too small to fit common items (10-25)
    // if the post_residual is in the "danger zone" (1..9), drastically increase the score.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead optimization: If the next item cannot fit in this post_residual,
    // apply a penalty to discourage creating a "stranded" bin.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 20.0;
    }

    // 3. Open bin pressure: Penalize opening a new bin if we have existing capacity.
    // If this is a new bin (bin_residual == bin_capacity), add a cost based on current bin count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // Reward using a new bin if existing bins are already very full (high mean_residual is low)
        score -= (100.0 - mean_residual) * 0.5;
    }

    // 4. Efficiency incentive: Favor bins that leave a residual capable of fitting the average item (approx 40-50).
    // This helps keep bins "balanced" for future arrivals.
    let ideal_residual = 45.0;
    score += (post_residual as f64 - ideal_residual).abs() * 0.1;

    // 5. Last chance bias: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Start with the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is too small for the next expected item (Lookahead).
    // If post_residual is smaller than the next item, we penalize it, unless the post_residual is near zero (perfect fit).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 5 {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Reward bins that bring the bin residual closer to the mean_residual of other bins.
    // This encourages uniformity, reducing the variance of remaining space across the set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // Strategic handling of the "New Bin" candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Only open a new bin if the current fitting options are extremely poor (many open bins, low efficiency).
        // If we have very few open bins, we should prefer filling existing ones.
        if open_bins_count > 0 {
            score += 45.0 + (open_bins_count as f64 * 0.5);
        }
    } else {
        // If this is the last bin that can fit the item, give it a significant priority boost.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Progress-based adjustment: As the stream nears the end, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
