    // We want to minimize post_residual to pack tightly
    let mut score = post;

    // Penalty for creating "slivers" (very small residuals that are hard to fill)
    // We penalize residuals in the range [1, 9] heavily, as they are mostly useless
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 15.0;
    }

    // Lookahead logic: if next_item_size fits in the post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic constraint: As the stream progresses, become more aggressive 
    // about filling existing bins rather than opening new ones.
    // If this is a new bin (post == bin_capacity - item_size), add a progression-based penalty.
    if bin_residual == bin_capacity {
