        // If there are other bins that could fit the item, penalize opening a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Coupling with mean_residual: avoid bins that are significantly "emptier" than the average
    // to keep the distribution of residuals tight.
    if bin_residual > (mean_residual as u32) {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // Smooth non-linear curvature: penalize large residuals quadratically 
    // to prioritize bins that are nearly full regardless of lookahead.
    score += (post * post) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits that leave little room
    // for small fragments that are difficult to fill (the "useless remainder" problem).
    // Penalize remainders between 1 and 9 (hard to fill) significantly.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
