        }
    }

    // 4. Harmonic/Fractional balancing: Favor bins that maintain a residual close to the
    // global mean to keep the packing density uniform across all active bins.
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.1;

    // 5. Progression scaling: As we approach the end of the stream, prioritize
    // closing existing bins (reducing open_bins_count) over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
