    // Penalize small residuals that are likely to become "dead space" (e.g., < 10 units)
    // We use a sigmoid-like penalty for post_residual < 10
    let dead_space_penalty = if post < 10.0 { (10.0 - post) * 5.0 } else { 0.0 };

    // Reward bins that keep the mean residual balanced relative to the current item's impact
    let residual_balance = (post - mean_residual).abs();

    // Lookahead logic: if we have a next item, penalize leaving a post_residual 
    // that is smaller than the next item if we could have fit it elsewhere.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Favor using existing bins over opening new ones as the stream progresses, 
    // but allow new bins if the current fit is extremely poor (large post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_bias = if is_new_bin {
        // As the stream progresses, make opening a new bin increasingly expensive
        (open_bins_count as f64 * 2.0) + (progress * 50.0)
    } else {
        0.0
    };

    // Combine factors:
    // 1. post: Best fit (smaller is generally better)
    // 2. dead_space_penalty: Avoid tiny slivers
    // 3. residual_balance: Keep bins uniform
    // 4. lookahead_penalty: Prepare for next item
    // 5. new_bin_bias: Control bin proliferation
    let score = post 
        + dead_space_penalty 
        + (residual_balance * 0.5) 
        + lookahead_penalty 
        + new_bin_bias;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual to keep space tight.
    // 2. Harmonic penalty: Penalize post_residuals that are too small to fit future items.
    // If post_residual < next_item_size, we create "dead space" that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0;
    }

    // 3. New bin threshold: If we have an empty bin, only use it if existing bins are poor fits.
    // Penalize opening a new bin if we have plenty of open bins that could work.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (open_bins_count as f64 * 0.5);
        }
    }

    // 4. Harmonic class bias: Favor bins that leave a residual which is a multiple of common item sizes (20, 25, 50).
    // This helps in packing items that fit into standard fractions of the capacity.
    if post_residual > 0 {
        let harmonic_penalty = (post_residual % 20) as f64 * 0.8;
        score += harmonic_penalty;
    }

    // 5. Lookahead efficiency: If this is the last chance for the current item, prioritize it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // 6. Global density balance: Avoid having too many bins with tiny residuals if it increases open_bins_count.
    if mean_residual < 15.0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: Avoid leaving small, unusable gaps (1-9).
    // If post_residual is in the range [1, 9], it is likely "dead" because 
    // the minimum item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If next_item_size exists, penalize bins that 
    // cannot fit the next item after the current one is placed.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bins pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless no other fitting bins exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong discouragement for opening new bins if alternatives exist.
            score += 100.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If it's the only choice, normalize the cost.
            score -= 10.0;
        }
    }

    // 4. Tightness bias: Favor bins that result in a tighter fit (smaller post_residual)
    // but only if they are not in the 'dead space' range.
    if post_residual >= 10 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 5. Global state normalization: Gradually increase preference for efficiency
    // as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += progress * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

