    }

    // 6. Last Chance Logic:
    // If this is the only bin that can fit the item, favor it heavily to avoid fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) that are too small to fit common future items.
    // We use a non-linear penalty: smaller residuals are worse if they are between 1 and 9.
    let fragmentation_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Favor bins that align with the lookahead (next_item_size).
    // If post_residual is close to next_item_size, we reward it.
    let lookahead_reward = if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        if diff < 5.0 { -20.0 } else { 0.0 }
    } else {
        0.0
    };

    // Adaptive threshold: as the stream progresses, become more conservative about opening new bins.
    // If bin_residual == bin_capacity, we are evaluating a NEW bin.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // As progress increases, the cost of opening a new bin increases quadratically.
        25.0 + (progress * 50.0).powi(2)
    } else {
        0.0
    };

    // Reward bins that keep the mean_residual high (balanced filling).
    let balance_reward = (post - mean_residual).powi(2) * 0.1;

    // Final score: lower is better.
    // post is the primary target (Best Fit).
    post + fragmentation_penalty + lookahead_reward + new_bin_penalty + balance_reward
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
