        if mean_residual > (bin_capacity as f64 * 0.4) {
            score -= (mean_residual - post_residual as f64) * 0.2;
        }
    }

    // 5. Last Chance Optimization:
    // If fitting_bins_count is 1, this is the only bin that can take the item.
    // We should reward taking it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Final scaling for density:
    // Penalize leaving very small, unusable gaps (e.g., < 5 units) if better options exist.
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the new bin case (bin_residual == bin_capacity) heavily as the stream progresses,
    // unless there are no other options.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + (open_bins_count as f64 * 5.0)
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: We want post_residual to be as small as possible.
    // However, we penalize values that are too small ("slivers") if they cannot 
    // accommodate common item sizes.
    let sliver_penalty = if post > 0.0 && post < 10.0 {
        20.0 / (post + 0.1)
    } else {
        0.0
    };

    // Lookahead logic: If the next item is large, prefer bins that leave enough space for it.
    // If the next item is small, prefer bins that are already tight.
    let lookahead_alignment = if next_item_size > 0 {
        if post >= next_item_size as f64 {
            -15.0 * (1.0 - progress) // Reward space for future large items early on
        } else {
            10.0 * progress // Penalize blocking future items late in the stream
        }
    } else {
        0.0
    };

    // Interaction with mean_residual: Encourage packing closer to the current average 
    // to keep bin utilization uniform.
    let uniformity_bonus = (post - mean_residual).abs() * 0.1;

    // Final score: lower is better.
    // Combine the base residual, penalties for bad fits, and lookahead incentives.
    post + new_bin_penalty + sliver_penalty + lookahead_alignment + uniformity_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "orphan" space that cannot fit common item sizes (10-80)
    // We penalize small residuals that are unlikely to accommodate the next item or future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: if the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Harmonic preference: favor bins that leave residuals close to common multiples (e.g., 20, 25, 33).
    // This helps aggregate items of similar sizes into specific bins.
    let harmonic_penalty = (post_residual % 25) as f64;
    score += harmonic_penalty;

    // If this is a new bin, penalize it relative to the average residual of existing bins.
    // Only open a new bin if the current fit is extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        score += mean_residual * 0.5;
        // Discourage opening new bins early in the process if fitting_bins_count is high.
        if fitting_bins_count > 0 {
            score += 60.0 * (1.0 - (step_index as f64 / total_items as f64));
        }
    }

    // If this bin is the last chance for the current item, reduce penalty to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creation of "unusable" gaps (1-9) which are statistically hard to fill.
    // If post_residual is in (0, 10), it is a high-risk dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If next_item_size is large, avoid leaving a tiny residual.
    // We prioritize bins that leave enough room for the next known item.
    if next_item_size > 0 {
