        score += (step_index as f64 / total_items as f64) * 10.0;
    } else {
        // Reward filling existing bins to minimize open_bins_count
        score -= (100.0 - mean_residual) * 0.1;
    }

    // 4. Strategic fit: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

