        // or if we are forced to (fitting_bins_count == 0).
        if fitting_bins_count > 0 && mean_residual > 20.0 {
            score += 150.0;
        } else {
            score += 80.0;
        }
    }

    // 4. Density Balancing: If we have many open bins, penalize creating more.
    score += (open_bins_count as f64) * 2.5;

    // 5. Progression Bias: As we approach the end of the stream, be more aggressive
    // about packing into existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
