    let density_pressure = (open_bins_count as f64 / 10.0) * progress;
    score += density_pressure * 5.0;

    // 4. Handling new bin creation
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current 'fitting_bins_count' are all very poor fits (e.g., leaving tiny gaps)
        // or if we are nearing the end of the stream and need to clear out remaining items.
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if we have existing capacity
            score += 45.0 + (mean_residual * 0.5);
        } else {
            // If nothing fits, opening a new bin is mandatory; set score low.
            score -= 100.0;
        }
    } else {
        // For existing bins, reward bins that are already "tight" to minimize fragmentation
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
