        score += (50.0 * (1.0 + progress)) + (mean_residual * 0.5);
    } else {
        // Encourage using bins that bring the residual closer to the global mean
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Final adjustment: Favor bins that are already well-utilized
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
