    // that is too small to fit any future item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // Penalty for creating "slivers" of unusable space.
    }

    // 2. Lookahead matching: Reward bins that become perfect fits for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // Strong reward for setting up a perfect fit.
        } else if post_residual > next_item_size {
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 20.0; // Penalty if next item cannot fit in this bin.
        }
    }

    // 3. New Bin Management: Discourage opening new bins unless necessary.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if existing ones can take the item.
            score += 100.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no bins fit, this is a necessary evil; normalize by capacity.
            score = 0.0;
        }
    }

    // 4. Global distribution alignment: Keep bin residuals near the mean.
    // This balances load across bins to prevent fragmentation.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // 5. Progression scaling: Be more aggressive early on, more conservative at the end.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
