    // If post_residual is small but > 0, we penalize it exponentially.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post).powf(1.5);
    }

    // Lookahead logic: If the next item could fit in the current post_residual, 
    // we reward this bin heavily.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 20.0 * (1.0 - progress);
    }

    // Interaction with global state:
    // If we have many open bins, we become more conservative about opening new ones.
    // If fitting_bins_count is 1, this is the last chance for this item in an existing bin.
    if bin_residual == bin_capacity {
        // This is a new bin. Penalize based on progress and current open bin count.
        // As the stream progresses, we want to be more efficient with new bin openings.
        score += 50.0 * (1.0 - progress) + (open_bins_count as f64 * 2.0);
    } else {
        // Favor bins that bring the residual closer to the global mean (balancing).
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want post_residual to be as close to 0 as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Favor residuals that align with common item sizes
    // If post_residual is a multiple of 20, it is more likely to accommodate future items.
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 3. Lookahead Integration: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Further reward if the fit is tight (e.g., leaving less than 10 units)
        if post_residual - next_item_size < 10 {
            score -= 20.0;
        }
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless no existing bins can fit the item or the mean residual of existing bins is poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing bin could take the item.
            score += 150.0 + (open_bins_count as f64 * 5.0);
        } else {
            // If no existing bin fits, prioritize the new bin.
            score -= 50.0;
        }
    }

    // 5. Global Efficiency: If the current bin is already very empty (high mean_residual), 
    // prefer placing items in bins that are already "half-full" to consolidate space.
    if (bin_capacity - bin_residual) < (bin_capacity / 2) {
        score += 10.0;
    }

    // 6. Progressive Scaling: As the stream nears the end, become more aggressive 
    // about fitting items into existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (progress * 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
