    let post = post_residual as f64;

    // Base score is the residual space remaining after placement.
    // Lower residual is generally better (Best Fit).
    let mut score = post;

    // Penalty for creating "dead space" (small residuals that are hard to fill later).
    // If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // prioritize this bin heavily to maximize packing density.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= (next_item_size as f64) * 1.5;
