    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0 + (mean_residual * 0.5);
    }

    // 4. Fitting Density: If this is the only bin that fits the current item, prioritize it heavily
    // to avoid unnecessary new bin openings.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive about filling
    // existing bins to avoid orphaned items in new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

