    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very high (wasteful)
        // or if we have no good choices.
        score += 40.0;
        score += (open_bins_count as f64) * 0.5;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // 4. Mean Residual Balancing: If the bin's post_residual is significantly 
    // better than the current mean_residual, reward it.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.8;
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // tighten the requirements for opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
