pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // We prioritize Best Fit (minimizing post_residual), but apply non-linear penalties
    // to discourage creating "slivers" (small residuals) that are unusable for future items.
    // A residual of 0 is perfect. A residual of 1..9 is often a "dead space" trap.
    let sliver_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Coupling: As the stream progresses, we become more conservative about opening new bins.
    // If fitting_bins_count is 1, we are at a "chokepoint" for this item.
    let chokepoint_urgency = if fitting_bins_count == 1 { -20.0 } else { 0.0 };

    // Lookahead influence: If the next item is large, we want to preserve space in current bins.
    // If the next item is small, we are less concerned with current bin tightness.
    let lookahead_pressure = if next_item_size > 60 {
        (post / bin_capacity as f64) * 10.0
    } else {
        -(post / bin_capacity as f64) * 5.0
    };

    // New bin candidate logic:
    // If bin_residual == bin_capacity, we are evaluating a brand new bin.
    // We penalize opening a new bin increasingly as we reach the end of the stream (progress -> 1.0).
    let new_bin_penalty = if bin_residual == bin_capacity {
        45.0 + (progress * 30.0) 
    } else {
        0.0
    };

    // Non-linear interaction: Penalize bins that are significantly emptier than the global mean
    // to encourage bin consolidation (Best Fit behavior).
    let consolidation_pressure = (residual - mean_residual).max(0.0) * 0.5;

    let mut score = post + sliver_penalty + chokepoint_urgency + lookahead_pressure + new_bin_penalty + consolidation_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
