    // We only want to open a new bin if the current mean_residual is very low (cluttered),
    // or if the current item is large and would leave a very poor residual in existing bins.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average space in existing bins is already very tight
