    // If only one bin fits the item, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 1000.0;
    }

    // Mean residual balancing:
    // Penalize bins that deviate too far from the current mean residual to keep bins uniform.
    let deviation = (post - mean_residual).abs();
    score += deviation * 10.0;

