}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic-based heuristic:
    // We prioritize bins that create post_residuals which are multiples of common item sizes (harmonic spacing).
    // We penalize "dead space" (post_residual < 10) unless it perfectly fits the next item.

    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize based on current bin usage to encourage packing into existing ones
    if bin_residual == bin_capacity {
        score += 50.0 + (open_bins_count as f64 * 2.5);
    }

    // 2. Harmonic penalty/reward: 
    // Small residuals are dangerous. If post_residual is < 10, it's likely wasted unless it's 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 3. Lookahead logic: 
    // If the next item fits perfectly into the post_residual, drastically reduce score.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= (100.0 / (fit_diff + 1.0)) * 0.5;
    }

    // 4. Distributional balance:
    // If we have many fitting bins, force Best-Fit behavior by penalizing larger post_residuals.
    if fitting_bins_count > 1 {
        score += (post_residual as f64) * 0.1;
    }

    // 5. Progression scaling:
    // As the stream nears the end, become more aggressive in packing to avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 6. Harmonic Modulo Constraint:
    // Penalize residuals that are not likely to accommodate standard item sizes (e.g., leaving a 5-residue)
    if post_residual % 10 != 0 && post_residual > 5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
