        // Penalize new bin creation if we have plenty of open bins already
        score += open_bins_count as f64 * 2.0;
    }

    // 6. Mean Residual Balancing:
    // Avoid creating bins that are significantly "emptier" than the current mean
    // to encourage packing items into existing "loose" bins.
    if (bin_residual as f64) > mean_residual {
