    // If post_residual is smaller than next_item_size, we penalize the bin 
    // to prevent blocking the future item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 * (1.0 - progress);
    }

    // Coupling with global state: if many bins are open, push to fill existing ones
    // rather than opening new ones.
    if open_bins_count > 0 {
        let density_penalty = (mean_residual - post_residual as f64).abs() * 0.5;
        score += density_penalty;
    }

    // Last chance logic: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1166: Harmonic-Residual Balancing
    // Strategy: Penalize small "fragment" residuals that are unlikely to accommodate future items,
    // while favoring placements that align with the harmonic mean of expected item sizes.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead zones" (residuals too small for most items, < 10)
    if post_residual > 0 && post_residual < 10 {
