    // We create a non-linear penalty for residuals between 1 and 9.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Reward placing items into bins that are already partially filled to pack tightly,
    // but scale this reward by progress to be more aggressive towards the end of the stream.
    let packing_efficiency = (bin_capacity as f64 - bin_residual as f64) * (1.0 + progress);

    // Lookahead logic: if the next item is large, penalize creating a small residual now
    // that won't fit the next item.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 2.5
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), apply a baseline cost
    // that increases as we have more bins open to discourage fragmentation.
    let new_bin_cost = if bin_residual == bin_capacity {
        150.0 + (open_bins_count as f64 * 5.0)
    } else {
        0.0
    };

    // Final score: Lower is better.
    // We minimize post_residual (Best Fit), add penalties for dead space and lookahead mismatches,
    // and subtract packing efficiency to favor bins that consolidate space.
    post + dead_space_penalty + lookahead_penalty + new_bin_cost - (packing_efficiency * 0.5)
