    // 3. Harmonic Class Logic: Prefer bins that leave "clean" remainders (multiples of 20 or 25)
    // This aligns with common item sizes (20, 25, 40, 50, etc.)
    if post_residual % 20 == 0 {
        score -= 15.0;
