        score -= 10.0;
    }

    // 4. Scarcity/Density Balance: 
    // If this is the last fitting bin, reward it to prevent premature new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Progression: As the stream nears the end, become more aggressive at filling bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

