    // We only want to open a new bin if the average residual is already high (fragmentation).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 30.0 {
            score = 45.0; // Moderate cost to open new bin if existing ones are fragmented
        } else {
            score = 60.0; // High cost to open new bin to discourage unnecessary new bins
        }
    }

    // 6. Progress factor: Be more aggressive about tight packing as the stream approaches completion.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize opening a new bin prematurely
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If we have many open bins, penalize opening another one heavily
        score += (open_bins_count as f64) * 2.0;
    }

    // Best-Fit strategy: Prefer bins where the post_residual is smallest (minimizes waste)
    // The base score is already post_residual, which inherently favors tighter fits.

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it later
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that have enough space for the next item
            score -= 15.0;
        } else {
            // Penalize bins that will be too small for the next item if they become "stranded"
            score += 5.0;
        }
    }

    // Dynamic threshold: As the stream progresses, become more aggressive about filling bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // Penalty for creating "unusable" gaps: avoid leaving small residuals that are hard to fill (1-9 range)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Normalize against mean_residual to avoid fragmentation
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Core objective: Minimize post_residual (Best Fit).
    // Penalize creating "dead space" (small residuals) that are likely unusable for future items.
    // Small residuals (1..10) are extremely dangerous; heavily penalize them.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        100.0 / post
    } else {
        0.0
    };

    // Factor in lookahead: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we effectively "waste" the bin's potential.
    let lookahead_penalty = if next_item_size > 0 && post < (next_item_size as f64) {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // Progression coupling: As the stream nears completion, become more aggressive in 
    // filling existing bins (lower score) to avoid opening new bins at the end.
    let progress_multiplier = 1.0 - (progress * 0.5);

    // New bin bias: If this is an empty bin (bin_residual == bin_capacity), 
    // only choose it if the fitting_bins_count is 0, or if the current progress 
    // suggests keeping bins open is more expensive than starting fresh.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_bias = if is_new_bin {
        if fitting_bins_count == 0 {
            0.0 // Necessary
        } else {
            // Penalize opening a new bin exponentially based on available open bins
            (open_bins_count as f64).powf(1.5) * 10.0
        }
    } else {
        0.0
    };

    // Combine:
    // 1. Base score is the residual (Best Fit).
    // 2. Add penalties for dead space and poor lookahead fit.
    // 3. Apply progression scaling.
    // 4. Add new bin bias.
    let score = (post + dead_space_penalty + lookahead_penalty) * progress_multiplier + new_bin_bias;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is < 10, it is likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Encourage "Best Fit" behavior but prioritize filling bins that are already sparse.
    // If we have many open bins, penalize opening a new one unless the fit is perfect.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0; // Penalty for opening a new bin unnecessarily
        }
    }

    // Lookahead logic: if the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic class logic: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This helps align bin space with standard item footprints.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // Penalize placements that leave a residual just below the average of open bins,
    // as this fragments the remaining capacity across the set.
    if (post_residual as f64) < mean_residual {
        score += 5.0;
    }

    // If this is the last bin that can fit the item, consider it a "must-use" to prevent
    // premature new bin creation if the fit is reasonably tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Progression weighting: As the stream nears the end, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space": gaps smaller than the smallest likely future item (approx 10)
    // are highly undesirable as they often become permanent waste.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Prioritize Best-Fit: Lower post_residual is usually better, but we modulate 
    // this by the number of bins available to avoid fragmenting too many bins.
    if fitting_bins_count > 1 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, 
    // highly prioritize this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Global Pressure: As we approach the end of the stream, prioritize closing 
    // bins (lower residual) over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: increases as we progress through the stream.
        score += 25.0 + (progress * 30.0);
    } else {
        // Reward for using existing bins, scaled by the mean residual to keep bins balanced.
        score -= (bin_capacity as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tight.
    // We favor bins where the remaining space is small.
    score += (post_residual as f64) * 0.5;

    // 2. Lookahead Matching: If the next item fits perfectly in the post_residual, 
    // heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.8;
    }

    // 3. Fragmentation Avoidance: If we create a small, unusable gap (e.g., < 10), 
    // it's often worse than opening a new bin for larger items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Mean Residual Balancing: If this bin's post_residual is significantly 
    // higher than the current average, penalize to force usage of other bins.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // 5. New Bin Threshold: If we are forced to open a new bin (fitting_bins_count == 0),
    // we make the new bin score neutral. If we have options, we penalize the new bin
    // relative to the stream progress to avoid early fragmentation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // As the stream progresses, opening new bins becomes increasingly expensive.
        score = 60.0 + (progress * 50.0);
    }

    // 6. Last Chance Logic: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: base cost is high, but decreases as we run out of items.
        // We only open a new bin if the best fit in existing bins is extremely poor (large post_residual).
        score = 45.0 + (progress * 20.0);
    } else {
        // Best-Fit Decreasing logic: minimize post_residual.
        // Penalize bins that leave very small gaps (e.g., 1-5), which are hard to fill later.
        if post_residual > 0 && post_residual <= 5 {
            score += 25.0;
        }

        // Lookahead: If next_item_size is large, prefer bins that can accommodate it.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0;
            } else {
                // If this bin cannot fit the next item, penalize it slightly more if it's nearing capacity.
                score += (next_item_size as f64 - post_residual as f64) * 0.2;
            }
        }

        // Global State: If we have many open bins, prioritize filling the ones with the lowest residuals.
        // If we have few open bins, prioritize creating room for future items.
        if fitting_bins_count == 1 {
            // Last chance penalty: Avoid leaving a bin with a tiny, unusable sliver.
            if post_residual < 10 {
                score += 10.0;
            }
        }

        // Dynamic scaling: As the stream progresses, tighten the requirement for "good" fits.
        score += (mean_residual - post_residual as f64) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Penalize large gaps that are too small for common items (e.g., < 10).
    let mut score = post_res;

    // Penalize opening new bins early in the stream unless necessary.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead: If next_item_size is large, avoid leaving small residuals
    // that cannot accommodate it (Best Fit Decreasing logic).
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += (next_item_size as f64 - post_res) * 0.5;
        }
    }

    // Encourage clustering: favor bins that remain close to the mean_residual
    // to keep the bin landscape uniform.
    let dev_from_mean = (post_res - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // Criticality: If this is the only bin that fits the item, aggressively 
    // reward placing it here to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Non-linear penalty for creating "dead zones" (residuals between 1 and 9),
    // as these are statistically likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // We emphasize the "tightness" of the fit.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead logic: If the next item can fit in the post_residual, reward this bin.
    // This effectively implements a basic Best-Fit-Decreasing-like lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. New Bin Penalty: Heavily penalize opening a new bin unless the current 
    // open bins are extremely inefficient (high mean_residual).
    if bin_residual == bin_capacity {
        // Higher mean_residual means existing bins are mostly empty, so a new bin is less egregious.
        // Lower mean_residual means existing bins are packed, so opening a new bin is expensive.
        score += 150.0 - (mean_residual * 1.2);
    }

    // 4. Scarcity/Bottleneck logic: If this is the only bin that can fit the item, 
    // we prioritize it to avoid forced new-bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Harmonic Class logic: Prefer residuals that are multiples of common item sizes (e.g., 20, 25).
    // This helps keep bins "aligned" for future items.
    let remainder = post_residual % 20;
    if remainder == 0 {
        score -= 10.0;
    } else if remainder > 15 {
        score += 5.0; // Penalize "sliver" remainders that are hard to fill
    }

    // 6. Progression dampening: As we reach the end of the stream, 
    // be more aggressive about closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (unusable gap < 10)
    // Small gaps are the primary cause of bin inefficiency.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Heuristic: If we have many open bins, we should be more aggressive 
