    }

    // If this is the only fitting bin, we are forced to use it. 
    // We apply a slight discount to prioritize using existing capacity 
    // over opening a new bin (which has post_residual == 100 - item_size).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalty for opening a new bin when existing bins are available.
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0 + (mean_residual * 0.2);
    }

    // Prefer bins that result in a residual close to the mean residual of others,
