}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger residuals (wasted space)
    // We want post_residual to be as close to 0 as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead optimization: If we can fit the next item perfectly (or near perfectly) 
    // in the resulting post_residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Reward small gaps that facilitate the next item (synergy)
        score -= (100.0 - gap).powf(1.2);
    }

    // 3. Prevent fragmentation: If this is the only bin that fits the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // 4. Global balance: If the current bin is significantly worse than the average 
    // residual, penalize it to encourage packing items into more "efficient" bins.
    if (post_residual as f64) > mean_residual {
        score += 50.0 * ((post_residual as f64) - mean_residual);
    }

    // 5. New bin penalty: Only open a new bin if the current fit is catastrophic (very large residual).
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already high (bins are messy)
        // or if we are at the start of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 200.0 + (mean_residual * 2.0) - (progress * 50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Strategy: Prefer Best-Fit (small post_residual) but penalize tiny "sliver" residuals
    // that cannot accommodate typical future items. Use lookahead to avoid blocking.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": residuals that are too small for almost any item (1..10)
    // but too large to be ignored.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - (post_residual as f64 * 4.5);
    }

    // 2. Lookahead logic: If the next item is large, prioritize keeping space available.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for blocking the next item if it's large
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
