    // If we have few bins, be more conservative about opening new ones.
    if is_new_bin {
        if open_bins_count > 0 {
            // High penalty for opening a new bin if we have existing capacity.
            score += 35.0 + (mean_residual * 0.5);
        }
    } else {
        // Reward bins that are already "half-full" to keep the number of active bins low.
        let utilization = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= utilization * 15.0;
    }

    // 4. Dynamic Time Horizon: As we reach the end of the stream, prioritize finishing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
