    // Lookahead logic: if the next item fits in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Harmonic preference: favor bins where the residual aligns with common item size patterns (multiples of 10).
    // This reduces fragmentation by keeping remaining capacities at "round" numbers.
    let alignment_penalty = (post_residual % 10) as f64 * 2.0;
    score += alignment_penalty;

    // If this is the only bin that fits the current item, avoid opening a new bin at all costs.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New bin thresholding: only open a new bin if the current fit is extremely poor (large post_residual left over).
    // We penalize opening a new bin (where bin_residual == bin_capacity) based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0);

        // If we are near the end of the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 100.0;
    }

    // Heuristic coupling: compare post_residual to the mean_residual of other bins.
    // If our post_residual is significantly lower than the mean, we are "tightening" the bin, which is good.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is often unusable
    // as items are at least 10. Penalize these "sliver" gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Integration: If the next item is large and won't fit in the current
    // post_residual, penalize the bin to save it for a better fit.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
