    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), add a threshold cost.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin; only choose if current options are worse.
        score += 45.0;

        // Dynamic scaling: as we approach the end of the stream, be more conservative.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 4. Fitting Constraint: If this is the last bin that can fit the item,
    // reward placing it here to avoid forced new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean residual alignment: Prefer bins that stay close to the average
    // to maintain uniformity across active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

