    // Favor bins that are already well-utilized (lower mean_residual)
    // Avoid opening new bins unless necessary (fitting_bins_count == 0)
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one fits
            50.0 + (mean_residual * 0.5)
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Lookahead logic: if next_item fits in current post_residual, reward this bin
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 * (post_r / bin_capacity as f64)
    } else {
        0.0
    };

    // Base score is the remaining space (Best Fit principle)
    // We want to minimize the post_residual to keep space tight
    let mut score = post_r + dead_space_penalty + new_bin_penalty + lookahead_bonus - completion_bonus;

    // Normalize for open bin count to prevent excessive fragmentation
    score += (open_bins_count as f64).powf(1.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
