    // 4. Fitting constraint: If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    // 5. Mean residual balancing: Prefer bins that keep the average residual high (more flexible).
    // If post_residual is much lower than the mean, it's a "tight fit" (usually good).
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items)
    // Residuals < 10 are often unusable for the given range (10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
