    // 3. Balance usage: avoid opening new bins if fit is decent
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for opening a new bin unless existing bins are very crowded
        score += 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Reward bins that keep the mean_residual stable
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // 4. Last chance logic:
    // If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    // 5. Progression scaling:
    // As we near the end of the stream, be more conservative with opening new bins
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Strategy: Prefer bins that leave little space (Best-Fit) while penalizing 
