    }

    // 2. Global state influence: If we are late in the stream, be more conservative 
    // with new bins (penalize opening new bins if we have plenty of open ones).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we progress through the stream.
        score += (open_bins_count as f64 * 2.0) + (progress * 50.0);
    }

