    }

    // 4. Fitting constraints: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Balance the load: If the current bin is significantly emptier than the 
    // mean of other open bins, favor filling it to keep the "fill level" balanced.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res_f = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We penalize small residuals that create "dead zones" (e.g., < 10) 
    // unless it's a perfect fit (post_residual == 0).
    let mut score = if post_residual == 0 {
        -50.0 // Strong reward for perfect packing
    } else if post_residual < 10 {
        25.0 // Penalty for leaving tiny slivers that are hard to fill
    } else {
        post_res_f
    };

    // Lookahead logic: If the next item fits into the current post_residual,
    // reward this bin heavily to facilitate future packing.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 * (1.0 - (next_item_size as f64 / post_res_f));
    }

    // Dynamic adjustment based on stream progress:
    // As we approach the end of the stream, we become more conservative
    // about opening new bins by penalizing the "New Bin" candidate (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        score += 30.0 + (progress * 40.0);
    }

    // Interaction with open_bins_count:
    // Avoid creating too many open bins if the average residual is already high.
    if open_bins_count > 0 {
        let utilization_factor = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += (open_bins_count as f64 * 5.0) * (1.0 - utilization_factor);
    }

    // If this is the only bin that fits, prioritize it over opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes
    // Modulo 10, 20, 25 are critical for capacity 100
    let harmonic_penalty = ((post_residual % 10) as f64) * 0.5;
    score += harmonic_penalty;

    // 3. Lookahead Logic: If next_item_size fits in post_residual, drastically reduce score
    if next_item_size > 0 && post_residual >= next_item_size {
