        }
    } else {
        // 5. Fragmentation Avoidance: If post_residual is small (e.g., < 10), 
        // it creates "dead space" that rarely fits future items. Penalize this.
        if post_residual < 10 {
            score += 20.0;
        }

        // 6. Encourage filling bins near capacity (Best Fit)
        // If post_residual is near 0, reward it heavily
        if post_residual < 5 {
            score -= 15.0;
        }
    }

    // 7. Dynamic Scaling based on progression
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "orphaned" gaps that are too small to fit future items.
    // We assume items are generally >= 10. A post_residual < 10 is almost always wasted space.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small but > 0, it is likely waste.
    // If post_residual is 0, it's a perfect fit (reward).
    if post_residual > 0 && post_residual < 10 {
