    } else if post_residual == 0 {
        score -= 20.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
