    }

    // 4. Fitting Density: If this is the only bin that can fit the item, we are forced to pick it.
    // We lower the score to ensure it is selected over the new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Global Efficiency: If the post_residual is significantly better than the current mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
