    // Penalize small residuals (dead space) quadratically to favor Best-Fit behavior.
    // The penalty is modulated by progress: as the stream nears the end, 
    // we become more desperate to fill gaps, so we reduce the penalty for small residuals.
    let dead_space_penalty = (post * post) * (1.0 - 0.5 * progress);

    // Lookahead logic: if the next item is large, prioritize keeping space open.
    // If next_item_size fits in the current post_residual, we reward this bin.
    let lookahead_reward = if next_item_size > 0 && post_residual >= next_item_size {
        -50.0 * (1.0 - progress)
    } else {
