    };

    // Balance the mean residual: discourage bins that deviate significantly from the average
    // state of the packing, which helps maintain uniform density.
    let density_balance = (post - mean_residual).abs() * 0.2;

    dead_space_penalty + lookahead_reward + new_bin_cost + density_balance
}

