    // We want to minimize post_residual (packing tightly).
    let mut score = post;

    // Penalty for creating "dead space": residuals that are too small to fit common items 
    // are often worse than slightly larger residuals.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if we know the next item, we penalize bins that cannot fit it 
    // if this is the only bin that could potentially have been saved for it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
