    // Heavily penalize opening new bins if there are valid fitting bins remaining,
    // scaled by how late we are in the stream (to prevent opening new bins near the end).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 100.0 * (1.0 + progress);
