    }

    // 4. Global state awareness:
    // If we have many open bins, prioritize filling them to consolidate.
    // If we are nearing the end of the stream, be more aggressive with packing.
    let consolidation_pressure = (open_bins_count as f64).sqrt() * (1.0 - progress);
    score += consolidation_pressure * 5.0;

    // 5. New bin handling:
    // Only open a new bin if the current fit is terrible (e.g., post_residual is very large)
