    // Already established by score = post_residual.

    // 2. Lookahead Matching: Reward bins that become perfect fits for the next item.
    // If post_residual is exactly next_item_size, we prioritize this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    }

    // 3. Fragmentation Avoidance: If post_residual is small (e.g., < 10), it creates unusable space.
    // Penalize "dead space" that is too small to fit any items (assuming minimum item size is ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Thresholding New Bin Opening:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // open bins are available. If fitting_bins_count > 0, we heavily penalize opening a new bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 90.0 + (fitting_bins_count as f64 * 15.0);
        } else {
            // If no bins can fit, opening a new bin is mandatory; make it neutral.
            score = 0.0;
        }
    }

    // 5. Mean Residual Balancing:
    // If the post_residual is significantly worse than the current mean, penalize it to 
    // encourage packing into bins that are already "tighter".
    if (post_residual as f64) > mean_residual {
        score += 15.0;
    }

    // 6. Progress Scaling:
    // As we approach the end of the stream, prioritize closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tightly packed.
    // We weight this by the proximity to capacity to avoid creating "orphaned" small spaces.
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // we prioritize this bin to maximize bin utilization efficiency.
    if next_item_size > 0 && post_residual >= next_item_size {
