    // 3. Fragmentation Control: If post_residual is in the "danger zone" (too small for most items),
    // we penalize it heavily to force usage of other bins or opening a new, cleaner bin.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    }

    // 4. Global State Awareness: If we are late in the stream, prioritize closing bins
    // by preferring bins that are already nearly full (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // 5. New Bin Thresholding: If this is an empty bin (new bin candidate),
    // calculate a cost based on the mean residual of existing bins.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins have very little space left
        // or if we have no good fits (fitting_bins_count is low).
        if mean_residual > 20.0 {
            score += 40.0;
        } else {
