        }
    }

    // 6. Scarcity Penalty: If this is the only bin that can fit the item,
    // lower its score to ensure we don't accidentally prefer a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
