pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post-residual (Best Fit).
    // We penalize leaving a small "sliver" of space (e.g., 1-5) as it is hard to fill.
    let sliver_penalty = if post_residual > 0 && post_residual < 6 {
        (6.0 - post_residual as f64) * 20.0
    } else {
        0.0
    };

    // Lookahead logic: If the next item is large, we want to reserve space for it.
    // If post_residual is smaller than the next item, we penalize this bin.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_residual as f64) * 1.5
    } else {
