    // We penalize opening new bins more aggressively as progress increases.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // High base cost for new bins, scaled by progress to force consolidation.
        50.0 + (progress * 100.0)
    } else {
        0.0
    };

    // Interaction between open_bins_count and mean_residual to prevent fragmentation.
    // We prefer bins that are closer to the mean residual of existing bins.
    let fragmentation_penalty = (post - mean_residual).abs() * 0.5;

    let mut score = post + sliver_penalty + lookahead_penalty + new_bin_penalty + fragmentation_penalty;

    // If this is the last chance for the item, lower the score of this bin to ensure it fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
