pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic/Modulo logic: Favor residuals that align with common item sizes (divisors of 100)
    // 3. Lookahead logic: If next_item_size fits in the post_residual, reward this bin heavily.

    // Penalize new bin creation unless necessary
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 150.0; // Strong penalty for opening a new bin unnecessarily
        }
    }

    // Penalty for leaving space that is too small for common item sizes (small bin fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward bins that can accommodate the next item (Lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    }

    // Harmonic alignment: Favor residuals that are multiples of 20 (factors of 100)
    // This helps maintain space for larger items later
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // If this is the last chance to fit the item in an existing bin, prioritize it strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Dynamic adjustment based on progression: late game, be more aggressive about filling gaps
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    // Favor bins that are already "near full" to keep the number of active bins low
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit future items.
    // If post_residual is in (0, 10), it creates "dead space" because min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Integration: If the next item exists, penalize bins that cannot fit it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins unless the fit is near-perfect (Best Fit Decreasing style).
    // If this is a new bin (bin_residual == bin_capacity), add pressure based on current open bin count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0) + 15.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the current bin is significantly worse than the mean, penalize it.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 6. Progress Scaling: As the stream nears the end, prioritize filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (gaps < 10 are rarely useful for items >= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. 2-Step Lookahead: Reward bins that can fit the next item perfectly or near-perfectly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact fit potential
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.8;
        } else {
            // Penalize if this bin will definitely NOT be able to accommodate the next item
            score += 20.0;
        }
    }

    // 3. Last Chance Heuristic: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 4. Distribution Balancing: Penalize bins that deviate significantly from the mean residual
    // to keep bin utilization uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. New Bin Penalty: Make opening a new bin expensive unless the fit is excellent
    if bin_residual == bin_capacity {
        score += 65.0;
        // If the current item is very large, it's safer to start a new bin than to 
        // pollute a bin that could have held two smaller items.
        if item_size > 70 {
            score -= 30.0;
        }
    }

    // 6. Progress factor: Be more aggressive in filling bins as we near the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is "too empty" (wasteful)
    // We prioritize bins that leave very little space (Best Fit)
    // However, we penalize small residuals that are too small to fit the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 45.0 * (1.0 - progress);
    }

    // Encourage filling bins that are already partially full
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fullness * 15.0;

    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already (avoid fragmentation)
        // or if we are near the end of the stream
        let threshold = 20.0 + (progress * 30.0);
        score += threshold;

        // If this is the only bin that can fit the item, we are forced to use it
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // If this bin can fit the item, favor it based on remaining capacity
        // Tight fits are generally better (Best Fit logic)
        score += post_residual as f64 * 0.5;

        // If this is the last chance to fit the item in existing bins, prioritize it
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // Global state adjustment: penalize high fragmentation across all bins
    if mean_residual > 30.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-placement residual.
    // We aim to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating a "sliver" (fragmentation):
    // If post_residual is small but > 0, it is harder to fill later.
    // We penalize values in the [1, 15] range non-linearly.
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post).powi(2) * 0.5;
    }

    // Lookahead logic: if the next item is large, prioritize keeping 
    // the current bin residual high enough to accommodate the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that cannot fit the next item if they are the only option
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Dynamic density management:
    // As the stream progresses, we become more conservative about opening new bins.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if 
        // the current mean_residual is very high (meaning we have space).
        // This effectively raises the barrier to open a new bin as progress increases.
        score += (open_bins_count as f64 * 5.0) * (1.0 + progress);
        score += mean_residual * 0.5;
    } else {
        // If the bin is already open, we favor bins that are closer to the 
        // current mean_residual to keep bin fullness uniform.
        let deviation = (post as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // Final adjustment: prioritize bins that are the "last chance" 
    // to fit the item before forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (dead space)
    // 2. Harmonic coupling: prioritize residuals that are multiples of common item sizes
    // Favor residuals that align with the next item size to maximize packing density
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        score += remainder as f64 * 0.5;

        // If post_residual is nearly perfect for the next item, reward heavily
        if post_residual >= next_item_size && (post_residual - next_item_size) < 5 {
            score -= 25.0;
        }
    }

    // 3. Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are very full (cannot fit item well)
        // or if fitting_bins_count is zero.
        if fitting_bins_count > 0 {
            score += 45.0; 
        } else {
            score -= 10.0;
        }
    }

    // 4. Harmonic thresholding: punish residuals that are too small to fit any common item (e.g. < 10)
    // but not zero (which is perfect).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 5. Global state normalization:
    // As the stream progresses, prioritize closing bins (lower mean_residual)
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
