    // If post_residual is in the range [1, 9], it's highly likely to become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins if we have existing capacity
    // If this is a new bin (bin_residual == bin_capacity), increase score based on existing open bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 3. Lookahead Logic: If the next item exists, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next item, we penalize it slightly
    // to encourage keeping larger gaps for future items.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // 4. Scarcity Reward: If this is the only bin that fits the item (fitting_bins_count == 1),
