pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score: punish large post_residual (Best Fit principle)
    // We want to minimize the gap to avoid fragmentation.
    let mut score = post;

    // Penalty for opening a new bin prematurely
    // As progress increases, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        score += (capacity * 0.4) + (progress * capacity * 0.6);
    }

    // Lookahead logic: if the next item is large, avoid leaving a tiny residual 
    // that won't fit anything. 
    // If next_item_size is 0, we are at the end, so maximize space utilization.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        // If post_residual is smaller than next_item_size, we create "dead space"
        if post < next {
            score += (next - post) * 1.5;
        }
    }

    // Coupling with open_bins_count: 
    // If we have many open bins, penalize creating a new one (encourage filling existing ones)
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).powf(1.2) * 5.0;
    }

    // Reward bins that have residuals close to the mean_residual of other bins
    // This promotes bin uniformity, which helps in future packing predictability.
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * 0.2;

    // Final scaling to ensure fitting bins are prioritized over new bins
    // unless the fit is extremely poor.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
