pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Strategy: Prefer Best-Fit, but penalize creating "dead zones" (residuals < 10) 
    // unless the item is large or the stream is nearing completion.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin with very little space left (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // If this is a new bin (bin_residual == capacity), penalize based on global load
    if bin_residual == bin_capacity {
        // Only open a new bin if we have too many nearly-full bins or if the item is large
        let load_factor = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += 25.0 + (load_factor * 15.0);

        // If we have other bins that could fit this, heavily penalize opening a new one
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    } else {
        // If it's an existing bin, check lookahead compatibility
        if next_item_size > 0 {
            // Reward bins that can accommodate the next item after this one
            if post_residual >= next_item_size {
                score -= 15.0;
            }
        }
    }

    // Dynamic horizon: As we approach the end of the stream, prioritize clearing bins (lower residuals)
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // Favor bins that are already "open" to keep the footprint small
    score += (open_bins_count as f64 * 0.5);

