    // If the bin's post_residual is significantly higher than the mean_residual 
    // of other bins, we are creating a "loose" bin, which is generally bad.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 4. Progress-aware density: 
    // As the stream progresses, prioritize tight packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}
